#pragma once

/**
 * @file CanvasWnd.h
 * @brief 그림을 그리는 캔버스 창 선언
 */

#include "ImageHistory.h"

/**
 * @brief 그리기 도구 종류
 */
enum class ToolType
{
    Pencil,     ///< 연필 (자유선)
    Eraser,     ///< 지우개
    Line,       ///< 직선
    Rectangle,  ///< 사각형
    Ellipse,    ///< 타원
};

/** @brief 캔버스가 부모 창에 보내는 알림 메시지. wParam은 CanvasNotify 값 */
constexpr UINT WM_CANVAS_NOTIFY = WM_APP + 1;

/**
 * @brief WM_CANVAS_NOTIFY의 wParam
 */
enum CanvasNotify : WPARAM
{
