     * @param color2 색 2 (오른쪽 버튼, 지우개 색)
     */
    void SetColors(COLORREF color1, COLORREF color2);

    /** @brief 실행 취소할 수 있는지 여부 */
    bool CanUndo() const;
    /** @brief 다시 실행할 수 있는지 여부 */
    bool CanRedo() const;
    /** @brief 실행 취소 */
    void Undo();
    /** @brief 다시 실행 */
    void Redo();

    /** @brief 마지막 저장 이후 수정되었는지 여부 */
    bool IsModified() const { return m_modified; }

    /** @brief 수정 여부를 지정합니다. (저장 후 false로) */
    void SetModified(bool modified);

    /** @brief 진행 중인 그리기 작업을 취소합니다. */
    void CancelOperation();

protected:
    afx_msg void OnPaint();
    afx_msg BOOL OnEraseBkgnd(CDC* pDC);
    afx_msg void OnSize(UINT nType, int cx, int cy);
    afx_msg void OnHScroll(UINT nSBCode, UINT nPos, CScrollBar* pScrollBar);
    afx_msg void OnVScroll(UINT nSBCode, UINT nPos, CScrollBar* pScrollBar);
    afx_msg BOOL OnMouseWheel(UINT nFlags, short zDelta, CPoint pt);
    afx_msg void OnMouseHWheel(UINT nFlags, short zDelta, CPoint pt);
    afx_msg void OnLButtonDown(UINT nFlags, CPoint point);
    afx_msg void OnLButtonUp(UINT nFlags, CPoint point);
    afx_msg void OnRButtonDown(UINT nFlags, CPoint point);
    afx_msg void OnRButtonUp(UINT nFlags, CPoint point);
    afx_msg void OnMouseMove(UINT nFlags, CPoint point);
    afx_msg void OnMouseLeave();
    afx_msg void OnCaptureChanged(CWnd* pWnd);
    afx_msg BOOL OnSetCursor(CWnd* pWnd, UINT nHitTest, UINT message);
    afx_msg UINT OnGetDlgCode();
    afx_msg void OnKeyDown(UINT nChar, UINT nRepCnt, UINT nFlags);
    afx_msg void OnKeyUp(UINT nChar, UINT nRepCnt, UINT nFlags);
    DECLARE_MESSAGE_MAP()

private:
    /** @brief 드래그 중인 마우스 버튼 */
    enum class DragButton { None, Left, Right };

    // --- 좌표 변환 ---
    CPoint ImageOrigin() const;                 ///< 이미지 (0,0)의 클라이언트 좌표
    CPoint ClientToImage(CPoint pt) const;      ///< 클라이언트 → 이미지 좌표
    CRect ImageToClient(const CRect& rc) const; ///< 이미지 → 클라이언트 좌표

    // --- 스크롤 ---
    void UpdateScrollBars();
    void ScrollTo(int x, int y);
    void HandleScroll(int bar, UINT code);

    // --- 그리기 ---
    void OnButtonDown(DragButton button, UINT nFlags, CPoint point);
    void OnButtonUp(DragButton button, CPoint point);
    void BeginDrag(DragButton button, CPoint imgPt);
    void ContinueFreehand(CPoint imgPt);
    void CommitDrag(CPoint imgPt);
    CPoint ConstrainShapeEnd(CPoint start, CPoint end, bool shift) const;
    void DrawShape(CDC& dc, CPoint start, CPoint end, COLORREF color) const;
    void DrawPencilSegment(CDC& dc, CPoint from, CPoint to, COLORREF color) const;
    CRect EraseSegment(CDC& dc, CPoint from, CPoint to);
    CRect EraserRect(CPoint center) const;
    void InvalidateImageRect(CRect rcImage);

    // --- 이미지/기록 ---
    ImageSnapshot CaptureSnapshot() const;
    void RestoreSnapshot(const ImageSnapshot& snapshot);
    bool CreateBlankImage(int width, int height);
    void ResetAfterImageChange();

    void NotifyParent(CanvasNotify code, LPARAM lParam = 0);
    void NotifyCursor(CPoint clientPt);

    bool IsShapeTool() const;
    int CurrentWidth() const { return GetToolWidth(m_tool, m_sizeLevel); }
    COLORREF DragColor() const;      ///< 드래그 중인 버튼의 색
    COLORREF DragOtherColor() const; ///< 드래그 중인 버튼의 반대 색

    CImage m_image;              ///< 확정된 이미지 (32비트 DIB)
    CImageHistory m_history;     ///< 실행 취소 기록
    ImageSnapshot m_beforeDrag;  ///< 드래그 시작 전 이미지 (확정 시 기록, 취소 시 복원)

    ToolType m_tool = ToolType::Pencil;
    int m_sizeLevel = 0;
    COLORREF m_color1 = RGB(0, 0, 0);
    COLORREF m_color2 = RGB(255, 255, 255);

    DragButton m_drag = DragButton::None;
    CPoint m_dragStart;          ///< 드래그 시작점 (이미지 좌표)
    CPoint m_dragLast;           ///< 직전 마우스 위치 (이미지 좌표)
    CPoint m_dragCurrent;        ///< 현재 도형 끝점 (Shift 제약 적용 후)

    CPoint m_scroll;             ///< 스크롤 위치 (픽셀)
    bool m_updatingScroll = false;
    bool m_trackingMouse = false;
    bool m_hoverValid = false;   ///< 지우개 미리 보기용 마우스 위치가 유효한지
    CPoint m_hoverPt;            ///< 마우스 위치 (이미지 좌표)

    bool m_modified = false;
};

