/**
 * @file CanvasWnd.cpp
 * @brief 캔버스 창 구현
 */
#include "pch.h"
#include "CanvasWnd.h"

#ifdef _DEBUG
#define new DEBUG_NEW
#endif

namespace
{
    constexpr int kMargin = 5;                           ///< 작업 영역 가장자리와 이미지 사이 여백
    constexpr int kShadow = 3;                           ///< 이미지 그림자 두께
    constexpr int kScrollLine = 20;                      ///< 스크롤 한 줄 (픽셀)
    constexpr COLORREF kWorkspaceColor = RGB(202, 212, 227);
    constexpr COLORREF kShadowColor = RGB(170, 181, 198);

    /** @brief COLORREF(0x00BBGGRR) → 32비트 DIB 픽셀(0x00RRGGBB) */
    inline uint32_t ToPixel(COLORREF c)
    {
        return (static_cast<uint32_t>(GetRValue(c)) << 16)
             | (static_cast<uint32_t>(GetGValue(c)) << 8)
             | static_cast<uint32_t>(GetBValue(c));
    }
}

BEGIN_MESSAGE_MAP(CCanvasWnd, CWnd)
    ON_WM_PAINT()
    ON_WM_ERASEBKGND()
    ON_WM_SIZE()
    ON_WM_HSCROLL()
    ON_WM_VSCROLL()
    ON_WM_MOUSEWHEEL()
    ON_WM_MOUSEHWHEEL()
    ON_WM_LBUTTONDOWN()
    ON_WM_LBUTTONUP()
    ON_WM_RBUTTONDOWN()
    ON_WM_RBUTTONUP()
    ON_WM_MOUSEMOVE()
    ON_WM_MOUSELEAVE()
    ON_WM_CAPTURECHANGED()
    ON_WM_SETCURSOR()
    ON_WM_GETDLGCODE()
    ON_WM_KEYDOWN()
    ON_WM_KEYUP()
END_MESSAGE_MAP()

CCanvasWnd::CCanvasWnd() = default;

BOOL CCanvasWnd::Create(CWnd* pParent, UINT nID)
{
    const CString cls = AfxRegisterWndClass(0, ::LoadCursor(nullptr, IDC_ARROW), nullptr, nullptr);
    return CWnd::CreateEx(0, cls, nullptr,
        WS_CHILD | WS_VISIBLE | WS_HSCROLL | WS_VSCROLL | WS_TABSTOP | WS_CLIPSIBLINGS,
        CRect(0, 0, 10, 10), pParent, nID);
}

// ---------------------------------------------------------------------------
// 이미지
// ---------------------------------------------------------------------------

bool CCanvasWnd::CreateBlankImage(int width, int height)
{
    CImage image;
    // 높이를 음수로 주면 위에서 아래 순서(top-down) DIB가 만들어집니다.
    if (width <= 0 || height <= 0 || !image.Create(width, -height, 32))
        return false;

    HDC hdc = image.GetDC();
    CDC::FromHandle(hdc)->FillSolidRect(0, 0, width, height, RGB(255, 255, 255));
    image.ReleaseDC();

    m_image.Destroy();
    m_image.Attach(image.Detach());
    return true;
}

bool CCanvasWnd::NewImage(int width, int height)
{
    CancelOperation();
    if (!CreateBlankImage(width, height))
        return false;
    ResetAfterImageChange();
    return true;
}

HRESULT CCanvasWnd::LoadFromFile(LPCTSTR path)
{
    CancelOperation();

    CImage src;
    HRESULT hr = src.Load(path);
    if (FAILED(hr))
        return hr;

    const int width = src.GetWidth();
    const int height = src.GetHeight();
    CImage dst;
    if (!dst.Create(width, -height, 32))
        return E_OUTOFMEMORY;

    // 투명한 부분이 검게 보이지 않도록 흰 바탕 위에 합성합니다.
    HDC hdc = dst.GetDC();
    CDC::FromHandle(hdc)->FillSolidRect(0, 0, width, height, RGB(255, 255, 255));
    src.Draw(hdc, 0, 0);
    dst.ReleaseDC();

    m_image.Destroy();
    m_image.Attach(dst.Detach());
    ResetAfterImageChange();
    return S_OK;
}

HRESULT CCanvasWnd::SaveToFile(LPCTSTR path)
{
    if (m_image.IsNull())
        return E_FAIL;

    // 어떤 형식으로든 문제없이 저장되도록 24비트로 변환해서 저장합니다.
    const CSize size = GetImageSize();
    CImage out;
    if (!out.Create(size.cx, size.cy, 24))
        return E_OUTOFMEMORY;
    HDC hdc = out.GetDC();
    m_image.BitBlt(hdc, 0, 0);
    out.ReleaseDC();

    return out.Save(path); // 형식은 확장자로 결정
}

CSize CCanvasWnd::GetImageSize() const
{
    if (m_image.IsNull())
        return CSize(0, 0);
    return CSize(m_image.GetWidth(), m_image.GetHeight());
}

ImageSnapshot CCanvasWnd::CaptureSnapshot() const
{
    ImageSnapshot snap;
    if (m_image.IsNull())
        return snap;

    GdiFlush(); // GDI로 그린 내용이 픽셀 메모리에 반영되도록
    snap.width = m_image.GetWidth();
    snap.height = m_image.GetHeight();
    snap.pixels.resize(static_cast<size_t>(snap.width) * snap.height);
    for (int y = 0; y < snap.height; ++y)
    {
        memcpy(&snap.pixels[static_cast<size_t>(y) * snap.width],
               m_image.GetPixelAddress(0, y), static_cast<size_t>(snap.width) * 4);
    }
    return snap;
}

void CCanvasWnd::RestoreSnapshot(const ImageSnapshot& snap)
{
    if (snap.IsEmpty())
        return;
    if (GetImageSize() != CSize(snap.width, snap.height))
    {
        if (!CreateBlankImage(snap.width, snap.height))
            return;
    }

    GdiFlush();
    for (int y = 0; y < snap.height; ++y)
    {
        memcpy(m_image.GetPixelAddress(0, y),
               &snap.pixels[static_cast<size_t>(y) * snap.width], static_cast<size_t>(snap.width) * 4);
    }
}

void CCanvasWnd::ResetAfterImageChange()
{
    m_history.Clear();
    m_modified = false;
    m_scroll = CPoint(0, 0);
    if (GetSafeHwnd())
    {
        UpdateScrollBars();
        Invalidate(FALSE);
    }
    NotifyParent(CN_STATE);
}

// ---------------------------------------------------------------------------
// 설정
// ---------------------------------------------------------------------------

void CCanvasWnd::SetTool(ToolType tool)
{
    CancelOperation();
    m_tool = tool;
    Invalidate(FALSE);
}

void CCanvasWnd::SetSizeLevel(int level)
{
    m_sizeLevel = std::clamp(level, 0, kSizeLevelCount - 1);
    Invalidate(FALSE);
}

int CCanvasWnd::GetToolWidth(ToolType tool, int level)
{
    static constexpr int kPencil[kSizeLevelCount] = { 1, 2, 3, 4 };
    static constexpr int kEraser[kSizeLevelCount] = { 4, 6, 8, 10 };
    static constexpr int kShape[kSizeLevelCount] = { 1, 3, 5, 8 };

    level = std::clamp(level, 0, kSizeLevelCount - 1);
    switch (tool)
    {
    case ToolType::Pencil: return kPencil[level];
    case ToolType::Eraser: return kEraser[level];
    default:               return kShape[level];
    }
}

void CCanvasWnd::SetColors(COLORREF color1, COLORREF color2)
{
    m_color1 = color1;
    m_color2 = color2;
}

bool CCanvasWnd::IsShapeTool() const
{
    return m_tool == ToolType::Line || m_tool == ToolType::Rectangle || m_tool == ToolType::Ellipse;
}

COLORREF CCanvasWnd::DragColor() const
{
    return m_drag == DragButton::Right ? m_color2 : m_color1;
}

COLORREF CCanvasWnd::DragOtherColor() const
{
    return m_drag == DragButton::Right ? m_color1 : m_color2;
}

// ---------------------------------------------------------------------------
// 실행 취소 / 다시 실행
// ---------------------------------------------------------------------------

bool CCanvasWnd::CanUndo() const
{
    return m_history.CanUndo();
}

bool CCanvasWnd::CanRedo() const
{
    return m_history.CanRedo();
}

void CCanvasWnd::Undo()
{
    CancelOperation();
    ImageSnapshot current = CaptureSnapshot();
    if (!m_history.Undo(current))
        return;
    RestoreSnapshot(current);
    m_modified = true;
    UpdateScrollBars();
    Invalidate(FALSE);
    NotifyParent(CN_STATE);
}

void CCanvasWnd::Redo()
{
    CancelOperation();
    ImageSnapshot current = CaptureSnapshot();
    if (!m_history.Redo(current))
        return;
    RestoreSnapshot(current);
    m_modified = true;
    UpdateScrollBars();
    Invalidate(FALSE);
    NotifyParent(CN_STATE);
}

void CCanvasWnd::SetModified(bool modified)
{
    m_modified = modified;
    NotifyParent(CN_STATE);
}

// ---------------------------------------------------------------------------
// 알림
// ---------------------------------------------------------------------------

void CCanvasWnd::NotifyParent(CanvasNotify code, LPARAM lParam)
{
    if (GetSafeHwnd() && GetParent())
        GetParent()->SendMessage(WM_CANVAS_NOTIFY, code, lParam);
}

void CCanvasWnd::NotifyCursor(CPoint clientPt)
{
    LPARAM value = -1;
    const CPoint img = ClientToImage(clientPt);
    const CSize size = GetImageSize();
    if (img.x >= 0 && img.y >= 0 && img.x < size.cx && img.y < size.cy)
        value = MAKELPARAM(img.x, img.y);

    if (value != m_lastCursorNotify)
    {
        m_lastCursorNotify = value;
        NotifyParent(CN_CURSOR, value);
    }
}

// ---------------------------------------------------------------------------
// 좌표 변환과 스크롤
// ---------------------------------------------------------------------------

CPoint CCanvasWnd::ImageOrigin() const
{
    return CPoint(kMargin - m_scroll.x, kMargin - m_scroll.y);
}

CPoint CCanvasWnd::ClientToImage(CPoint pt) const
{
    return pt - ImageOrigin();
}

CRect CCanvasWnd::ImageToClient(const CRect& rc) const
{
    CRect out = rc;
    out.OffsetRect(ImageOrigin());
    return out;
}

void CCanvasWnd::UpdateScrollBars()
{
    if (m_updatingScroll || !GetSafeHwnd())
        return;
    m_updatingScroll = true;

    const CSize content = GetImageSize() + CSize(kMargin * 2 + kShadow, kMargin * 2 + kShadow);

    // 스크롤바가 생기거나 사라지면 클라이언트 영역이 바뀌므로 두 번 계산합니다.
    for (int pass = 0; pass < 2; ++pass)
    {
        CRect rc;
        GetClientRect(&rc);
        m_scroll.x = std::clamp(m_scroll.x, 0, std::max(0, content.cx - rc.Width()));
        m_scroll.y = std::clamp(m_scroll.y, 0, std::max(0, content.cy - rc.Height()));

        SCROLLINFO si{ sizeof(SCROLLINFO) };
        si.fMask = SIF_RANGE | SIF_PAGE | SIF_POS;
        si.nMin = 0;
        si.nMax = content.cx - 1;
        si.nPage = static_cast<UINT>(rc.Width());
        si.nPos = m_scroll.x;
        SetScrollInfo(SB_HORZ, &si, TRUE);

        si.nMax = content.cy - 1;
        si.nPage = static_cast<UINT>(rc.Height());
        si.nPos = m_scroll.y;
        SetScrollInfo(SB_VERT, &si, TRUE);
    }

    m_updatingScroll = false;
}

void CCanvasWnd::ScrollTo(int x, int y)
{
    CRect rc;
    GetClientRect(&rc);
    const CSize content = GetImageSize() + CSize(kMargin * 2 + kShadow, kMargin * 2 + kShadow);
    x = std::clamp(x, 0, std::max(0, content.cx - rc.Width()));
    y = std::clamp(y, 0, std::max(0, content.cy - rc.Height()));
    if (x == m_scroll.x && y == m_scroll.y)
        return;

    m_scroll = CPoint(x, y);
    SetScrollPos(SB_HORZ, x, TRUE);
    SetScrollPos(SB_VERT, y, TRUE);
    Invalidate(FALSE);
}

void CCanvasWnd::HandleScroll(int bar, UINT code)
{
    SCROLLINFO si{ sizeof(SCROLLINFO) };
    si.fMask = SIF_ALL;
    GetScrollInfo(bar, &si);

    int pos = si.nPos;
    switch (code)
    {
    case SB_LINEUP:        pos -= kScrollLine; break;
    case SB_LINEDOWN:      pos += kScrollLine; break;
    case SB_PAGEUP:        pos -= static_cast<int>(si.nPage); break;
    case SB_PAGEDOWN:      pos += static_cast<int>(si.nPage); break;
    case SB_THUMBTRACK:
    case SB_THUMBPOSITION: pos = si.nTrackPos; break; // 32비트 위치
    case SB_TOP:           pos = si.nMin; break;
    case SB_BOTTOM:        pos = si.nMax; break;
    default:               return;
    }

    if (bar == SB_HORZ)
        ScrollTo(pos, m_scroll.y);
    else
        ScrollTo(m_scroll.x, pos);
}

void CCanvasWnd::OnSize(UINT nType, int cx, int cy)
{
    CWnd::OnSize(nType, cx, cy);
    UpdateScrollBars();
    Invalidate(FALSE);
}

void CCanvasWnd::OnHScroll(UINT nSBCode, UINT /*nPos*/, CScrollBar* /*pScrollBar*/)
{
    HandleScroll(SB_HORZ, nSBCode);
}

void CCanvasWnd::OnVScroll(UINT nSBCode, UINT /*nPos*/, CScrollBar* /*pScrollBar*/)
{
    HandleScroll(SB_VERT, nSBCode);
}

BOOL CCanvasWnd::OnMouseWheel(UINT nFlags, short zDelta, CPoint /*pt*/)
{
    UINT lines = 3;
    SystemParametersInfo(SPI_GETWHEELSCROLLLINES, 0, &lines, 0);
    const int amount = -MulDiv(zDelta, static_cast<int>(lines) * kScrollLine, WHEEL_DELTA);

    if (nFlags & MK_SHIFT) // Shift + 휠: 가로 스크롤
        ScrollTo(m_scroll.x + amount, m_scroll.y);
    else
        ScrollTo(m_scroll.x, m_scroll.y + amount);
    return TRUE;
}

void CCanvasWnd::OnMouseHWheel(UINT /*nFlags*/, short zDelta, CPoint /*pt*/)
{
    ScrollTo(m_scroll.x + MulDiv(zDelta, 3 * kScrollLine, WHEEL_DELTA), m_scroll.y);
}

// ---------------------------------------------------------------------------
// 화면 출력 (더블 버퍼링)
// ---------------------------------------------------------------------------

BOOL CCanvasWnd::OnEraseBkgnd(CDC* /*pDC*/)
{
    return TRUE; // OnPaint에서 전부 그리므로 배경 지우기를 생략 (깜박임 방지)
}

void CCanvasWnd::OnPaint()
{
    CPaintDC dc(this);

    CRect client;
    GetClientRect(&client);
    if (client.IsRectEmpty())
        return;

    CDC mem;
    mem.CreateCompatibleDC(&dc);
    CBitmap bmp;
    bmp.CreateCompatibleBitmap(&dc, client.Width(), client.Height());
    CBitmap* pOldBmp = mem.SelectObject(&bmp);

    mem.FillSolidRect(client, kWorkspaceColor);

    if (!m_image.IsNull())
    {
        const CPoint org = ImageOrigin();
        const CSize size = GetImageSize();

        mem.FillSolidRect(org.x + kShadow, org.y + kShadow, size.cx, size.cy, kShadowColor);
        m_image.BitBlt(mem.GetSafeHdc(), org.x, org.y, size.cx, size.cy, 0, 0);

        // 이후는 이미지 좌표로 그리고, 이미지 밖으로는 나가지 않게 자릅니다.
        const int saved = mem.SaveDC();
        mem.SetViewportOrg(org);
        mem.IntersectClipRect(0, 0, size.cx, size.cy);

        if (m_drag != DragButton::None && IsShapeTool())
            DrawShape(mem, m_dragStart, m_dragCurrent, DragColor());

        if (m_tool == ToolType::Eraser && m_hoverValid)
        {
            CBrush black(RGB(0, 0, 0));
            mem.FrameRect(EraserRect(m_hoverPt), &black);
        }

        mem.RestoreDC(saved);
    }

    dc.BitBlt(0, 0, client.Width(), client.Height(), &mem, 0, 0, SRCCOPY);
    mem.SelectObject(pOldBmp);
}

void CCanvasWnd::InvalidateImageRect(CRect rcImage)
{
    rcImage.InflateRect(2, 2);
    InvalidateRect(ImageToClient(rcImage), FALSE);
}

// ---------------------------------------------------------------------------
// 그리기 도구
// ---------------------------------------------------------------------------

void CCanvasWnd::DrawStrokeSegment(CDC& dc, CPoint from, CPoint to, COLORREF color) const
{
    const int width = CurrentWidth();
    if (width <= 1)
    {
        CPen pen(PS_SOLID, 1, color);
        CPen* pOld = dc.SelectObject(&pen);
        dc.MoveTo(from);
        dc.LineTo(to);
        dc.SelectObject(pOld);
        dc.SetPixelV(to, color); // LineTo는 끝점을 그리지 않음
        return;
    }

    if (from == to)
    {
        // 길이가 0인 선은 그려지지 않으므로 원으로 점을 찍습니다.
        CBrush brush(color);
        CBrush* pOldBrush = dc.SelectObject(&brush);
        CGdiObject* pOldPen = dc.SelectStockObject(NULL_PEN);
        const int left = to.x - width / 2;
        const int top = to.y - width / 2;
        dc.Ellipse(left, top, left + width + 1, top + width + 1); // NULL_PEN이면 오른쪽/아래 1px 덜 그려짐
        dc.SelectObject(pOldPen);
        dc.SelectObject(pOldBrush);
        return;
    }

    LOGBRUSH lb{ BS_SOLID, color, 0 };
    CPen pen(PS_GEOMETRIC | PS_SOLID | PS_ENDCAP_ROUND | PS_JOIN_ROUND, width, &lb);
    CPen* pOld = dc.SelectObject(&pen);
    dc.MoveTo(from);
    dc.LineTo(to);
    dc.SelectObject(pOld);
}

CRect CCanvasWnd::EraserRect(CPoint center) const
{
    const int size = CurrentWidth();
    const int left = center.x - size / 2;
    const int top = center.y - size / 2;
    return CRect(left, top, left + size, top + size);
}

CRect CCanvasWnd::EraseSegment(CDC& dc, CPoint from, CPoint to)
{
    // 두 점 사이를 1픽셀 간격으로 보간하며 사각형을 찍습니다.
    const int steps = std::max(std::abs(to.x - from.x), std::abs(to.y - from.y));
    const CRect bounds(CPoint(0, 0), GetImageSize());
    CRect dirty;
    dirty.SetRectEmpty();

    const bool replaceMode = (m_drag == DragButton::Right);
    const uint32_t target = ToPixel(m_color1);
    const uint32_t replacement = ToPixel(m_color2);
    if (replaceMode)
        GdiFlush();

    for (int i = 0; i <= steps; ++i)
    {
        CPoint p = from;
        if (steps > 0)
        {
            p.x = from.x + MulDiv(to.x - from.x, i, steps);
            p.y = from.y + MulDiv(to.y - from.y, i, steps);
        }

        CRect rc = EraserRect(p);
        if (!rc.IntersectRect(rc, bounds))
            continue;

        if (!replaceMode)
        {
            // 왼쪽 버튼: 색 2로 칠함
            dc.FillSolidRect(rc, m_color2);
        }
        else
        {
            // 오른쪽 버튼: 색 1인 픽셀만 색 2로 바꿈
            for (int y = rc.top; y < rc.bottom; ++y)
            {
                auto* row = static_cast<uint32_t*>(m_image.GetPixelAddress(0, y));
                for (int x = rc.left; x < rc.right; ++x)
                {
                    if ((row[x] & 0x00FFFFFF) == target)
                        row[x] = replacement;
                }
            }
        }
        dirty.UnionRect(dirty, rc);
    }
    return dirty;
}

CPoint CCanvasWnd::ConstrainShapeEnd(CPoint start, CPoint end, bool shift) const
{
    if (!shift)
        return end;

    const int dx = end.x - start.x;
    const int dy = end.y - start.y;
    const int adx = std::abs(dx);
    const int ady = std::abs(dy);
    const int sx = dx < 0 ? -1 : 1;
    const int sy = dy < 0 ? -1 : 1;

    if (m_tool == ToolType::Line)
    {
        // 0°, 45°, 90° 중 가까운 방향으로 고정 (tan 22.5° ≈ 0.414)
        if (ady * 1000 < adx * 414)
            return CPoint(end.x, start.y);
        if (adx * 1000 < ady * 414)
            return CPoint(start.x, end.y);
    }

    // 정사각형/정원 또는 45° 대각선
    const int d = std::max(adx, ady);
    return CPoint(start.x + sx * d, start.y + sy * d);
}

void CCanvasWnd::DrawShape(CDC& dc, CPoint start, CPoint end, COLORREF color) const
{
    if (m_tool == ToolType::Line)
    {
        DrawStrokeSegment(dc, start, end, color);
        return;
    }

    CRect rc(start, end);
    rc.NormalizeRect();
    rc.right += 1; // 드래그한 끝 픽셀까지 포함
    rc.bottom += 1;

    // PS_INSIDEFRAME: 굵기가 두꺼워도 선이 드래그한 사각형 안쪽에 그려짐
    CPen pen(PS_INSIDEFRAME, CurrentWidth(), color);
    CPen* pOldPen = dc.SelectObject(&pen);
    CGdiObject* pOldBrush = dc.SelectStockObject(NULL_BRUSH);
    if (m_tool == ToolType::Rectangle)
        dc.Rectangle(rc);
    else
        dc.Ellipse(rc);
    dc.SelectObject(pOldBrush);
    dc.SelectObject(pOldPen);
}

void CCanvasWnd::BeginDrag(DragButton button, CPoint imgPt)
{
    if (m_image.IsNull())
        return;

    m_beforeDrag = CaptureSnapshot();
    m_drag = button;
    m_dragStart = m_dragLast = m_dragCurrent = imgPt;
    SetCapture();

    if (IsShapeTool())
    {
        Invalidate(FALSE);
        return;
    }

    // 자유선 도구는 누른 자리에 바로 점을 찍습니다.
    HDC hdc = m_image.GetDC();
    CDC* pDC = CDC::FromHandle(hdc);
    CRect dirty;
    if (m_tool == ToolType::Eraser)
    {
        dirty = EraseSegment(*pDC, imgPt, imgPt);
    }
    else
    {
        DrawStrokeSegment(*pDC, imgPt, imgPt, DragColor());
        dirty = CRect(imgPt, imgPt);
        dirty.InflateRect(CurrentWidth(), CurrentWidth());
    }
    m_image.ReleaseDC();
    InvalidateImageRect(dirty);
}

void CCanvasWnd::ContinueFreehand(CPoint imgPt)
{
    if (imgPt == m_dragLast)
        return;

    HDC hdc = m_image.GetDC();
    CDC* pDC = CDC::FromHandle(hdc);
    CRect dirty;
    if (m_tool == ToolType::Eraser)
    {
        dirty = EraseSegment(*pDC, m_dragLast, imgPt);
    }
    else
    {
        DrawStrokeSegment(*pDC, m_dragLast, imgPt, DragColor());
        dirty = CRect(m_dragLast, imgPt);
        dirty.NormalizeRect();
        dirty.InflateRect(CurrentWidth(), CurrentWidth());
    }
    m_image.ReleaseDC();
    InvalidateImageRect(dirty);
}

void CCanvasWnd::CommitDrag(CPoint imgPt)
{
    if (IsShapeTool())
    {
        m_dragCurrent = ConstrainShapeEnd(m_dragStart, imgPt, GetKeyState(VK_SHIFT) < 0);
        HDC hdc = m_image.GetDC();
        DrawShape(*CDC::FromHandle(hdc), m_dragStart, m_dragCurrent, DragColor());
        m_image.ReleaseDC();
    }
    else
    {
        ContinueFreehand(imgPt);
    }

    m_history.Push(std::move(m_beforeDrag));
    m_beforeDrag = ImageSnapshot();
    m_modified = true;

    m_drag = DragButton::None; // ReleaseCapture → OnCaptureChanged에서 취소되지 않도록 먼저 바꿈
    ReleaseCapture();
    Invalidate(FALSE);
    NotifyParent(CN_STATE);
}

void CCanvasWnd::CancelOperation()
{
    if (m_drag == DragButton::None)
        return;

    const bool freehand = !IsShapeTool();
    m_drag = DragButton::None;
    if (GetCapture() == this)
        ReleaseCapture();

    if (freehand)
        RestoreSnapshot(m_beforeDrag); // 이미 그린 획을 되돌림
    m_beforeDrag = ImageSnapshot();
    Invalidate(FALSE);
}

// ---------------------------------------------------------------------------
// 마우스와 키보드
// ---------------------------------------------------------------------------

void CCanvasWnd::OnButtonDown(DragButton button, UINT /*nFlags*/, CPoint point)
{
    SetFocus();
    if (m_drag != DragButton::None)
    {
        // 그리는 도중 반대쪽 버튼을 누르면 그리던 것을 취소 (Windows 그림판과 같은 동작)
        if (m_drag != button)
            CancelOperation();
        return;
    }
    BeginDrag(button, ClientToImage(point));
}

void CCanvasWnd::OnButtonUp(DragButton button, CPoint point)
{
    if (m_drag == button)
        CommitDrag(ClientToImage(point));
}

void CCanvasWnd::OnLButtonDown(UINT nFlags, CPoint point)
{
    OnButtonDown(DragButton::Left, nFlags, point);
}

void CCanvasWnd::OnLButtonUp(UINT /*nFlags*/, CPoint point)
{
    OnButtonUp(DragButton::Left, point);
}

void CCanvasWnd::OnRButtonDown(UINT nFlags, CPoint point)
{
    OnButtonDown(DragButton::Right, nFlags, point);
}

void CCanvasWnd::OnRButtonUp(UINT /*nFlags*/, CPoint point)
{
    OnButtonUp(DragButton::Right, point);
}

void CCanvasWnd::OnMouseMove(UINT nFlags, CPoint point)
{
    if (!m_trackingMouse)
    {
        TRACKMOUSEEVENT tme{ sizeof(TRACKMOUSEEVENT), TME_LEAVE, m_hWnd, 0 };
        m_trackingMouse = TrackMouseEvent(&tme) != FALSE;
    }

    const CPoint img = ClientToImage(point);
    NotifyCursor(point);

    if (m_tool == ToolType::Eraser)
    {
        if (m_hoverValid)
            InvalidateImageRect(EraserRect(m_hoverPt));
        InvalidateImageRect(EraserRect(img));
    }
    m_hoverPt = img;
    m_hoverValid = true;

    if (m_drag == DragButton::None)
        return;

    if (IsShapeTool())
    {
        m_dragCurrent = ConstrainShapeEnd(m_dragStart, img, (nFlags & MK_SHIFT) != 0);
        Invalidate(FALSE);
    }
    else
    {
        ContinueFreehand(img);
    }
    m_dragLast = img;
}

void CCanvasWnd::OnMouseLeave()
{
    m_trackingMouse = false;
    if (m_hoverValid && m_tool == ToolType::Eraser)
        InvalidateImageRect(EraserRect(m_hoverPt));
    m_hoverValid = false;
    m_lastCursorNotify = -2;
    NotifyParent(CN_CURSOR, -1);
}

void CCanvasWnd::OnCaptureChanged(CWnd* pWnd)
{
    // 다른 창이 마우스를 가져가면 (Alt+Tab 등) 그리던 것을 취소
    if (pWnd != this && m_drag != DragButton::None)
        CancelOperation();
    CWnd::OnCaptureChanged(pWnd);
}

BOOL CCanvasWnd::OnSetCursor(CWnd* pWnd, UINT nHitTest, UINT message)
{
    if (nHitTest == HTCLIENT)
    {
        CPoint pt;
        GetCursorPos(&pt);
        ScreenToClient(&pt);
        const CPoint img = ClientToImage(pt);
        const CSize size = GetImageSize();
        const bool overImage = img.x >= 0 && img.y >= 0 && img.x < size.cx && img.y < size.cy;

        if (overImage || m_drag != DragButton::None)
        {
            // 지우개는 사각형 미리 보기로 위치를 보여 주므로 커서를 숨깁니다.
            ::SetCursor(m_tool == ToolType::Eraser ? nullptr : ::LoadCursor(nullptr, IDC_CROSS));
            return TRUE;
        }
    }
    return CWnd::OnSetCursor(pWnd, nHitTest, message);
}

UINT CCanvasWnd::OnGetDlgCode()
{
    return DLGC_WANTALLKEYS; // Esc, Shift를 대화 상자가 가로채지 않도록
}

void CCanvasWnd::OnKeyDown(UINT nChar, UINT nRepCnt, UINT nFlags)
{
    if (nChar == VK_ESCAPE)
    {
        CancelOperation();
        return;
    }
    if (nChar == VK_SHIFT && m_drag != DragButton::None && IsShapeTool())
    {
        m_dragCurrent = ConstrainShapeEnd(m_dragStart, m_dragLast, true);
        Invalidate(FALSE);
        return;
    }
    CWnd::OnKeyDown(nChar, nRepCnt, nFlags);
}

void CCanvasWnd::OnKeyUp(UINT nChar, UINT nRepCnt, UINT nFlags)
{
    if (nChar == VK_SHIFT && m_drag != DragButton::None && IsShapeTool())
    {
        m_dragCurrent = ConstrainShapeEnd(m_dragStart, m_dragLast, false);
        Invalidate(FALSE);
        return;
    }
    CWnd::OnKeyUp(nChar, nRepCnt, nFlags);
}

