/**
 * @file ColorPanel.cpp
 * @brief 색 선택 패널 구현
 */
#include "pch.h"
#include "ColorPanel.h"

#ifdef _DEBUG
#define new DEBUG_NEW
#endif

BEGIN_MESSAGE_MAP(CColorPanel, CWnd)
    ON_WM_PAINT()
    ON_WM_ERASEBKGND()
    ON_WM_LBUTTONDOWN()
    ON_WM_RBUTTONDOWN()
END_MESSAGE_MAP()

CColorPanel::CColorPanel()
    : m_palette{
        // Windows 그림판의 기본 20색 (위 두 줄은 진한 색, 아래 두 줄은 밝은 색)
        RGB(0, 0, 0),       RGB(127, 127, 127), RGB(136, 0, 21),    RGB(237, 28, 36),
        RGB(255, 127, 39),  RGB(255, 242, 0),   RGB(34, 177, 76),   RGB(0, 162, 232),
        RGB(63, 72, 204),   RGB(163, 73, 164),  RGB(255, 255, 255), RGB(195, 195, 195),
        RGB(185, 122, 87),  RGB(255, 174, 201), RGB(255, 201, 14),  RGB(239, 228, 176),
        RGB(181, 230, 29),  RGB(153, 217, 234), RGB(112, 146, 190), RGB(200, 191, 231) }
{
    for (COLORREF& c : m_customColors)
        c = RGB(255, 255, 255);
}

void CColorPanel::CalcLayout(CRect& rcColor1, CRect& rcColor2, int& labelTop, int& cell, CPoint& paletteOrg) const
{
    CRect client;
    GetClientRect(&client);
    const int dpi = static_cast<int>(GetDpiForWindow(m_hWnd));
    const int gap = MulDiv(4, dpi, 96);
    const int labelHeight = MulDiv(16, dpi, 96);

    // 위: 색 상자 한 줄(셀 높이) + 글자, 아래: 팔레트 kRows 줄 → 셀 크기가 들어가는 만큼
    cell = std::min(client.Width() / kColumns, (client.Height() - labelHeight - gap) / (kRows + 1));
    cell = std::max(cell, 4);

    const int boxWidth = (cell * kColumns - gap) / 2;
    rcColor1 = CRect(0, 0, boxWidth, cell);
    rcColor2 = CRect(boxWidth + gap, 0, boxWidth * 2 + gap, cell);
    labelTop = cell;
    paletteOrg = CPoint(0, cell + labelHeight + gap);
}

CRect CColorPanel::PaletteCellRect(int index) const
{
    CRect rc1, rc2;
    int labelTop = 0, cell = 0;
    CPoint org;
    CalcLayout(rc1, rc2, labelTop, cell, org);

    const int col = index % kColumns;
    const int row = index / kColumns;
    return CRect(org.x + col * cell, org.y + row * cell, org.x + (col + 1) * cell, org.y + (row + 1) * cell);
}

int CColorPanel::HitTest(CPoint pt) const
{
    CRect rc1, rc2;
    int labelTop = 0, cell = 0;
    CPoint org;
    CalcLayout(rc1, rc2, labelTop, cell, org);

    // 상자 아래 글자 부분을 눌러도 해당 색으로 판정
    CRect hit1 = rc1, hit2 = rc2;
    hit1.bottom = org.y;
    hit2.bottom = org.y;
    if (hit1.PtInRect(pt))
        return HitColor1;
    if (hit2.PtInRect(pt))
        return HitColor2;

    for (int i = 0; i < kPaletteCount; ++i)
    {
        if (PaletteCellRect(i).PtInRect(pt))
            return i;
    }
    return HitNone;
}

BOOL CColorPanel::OnEraseBkgnd(CDC* /*pDC*/)
{
    return TRUE;
}

void CColorPanel::OnPaint()
{
    CPaintDC dc(this);
    CRect client;
    GetClientRect(&client);

    CDC mem;
    mem.CreateCompatibleDC(&dc);
    CBitmap bmp;
    bmp.CreateCompatibleBitmap(&dc, client.Width(), client.Height());
    CBitmap* pOldBmp = mem.SelectObject(&bmp);
    mem.FillSolidRect(client, GetSysColor(COLOR_BTNFACE));

    CRect rc1, rc2;
    int labelTop = 0, cell = 0;
    CPoint org;
    CalcLayout(rc1, rc2, labelTop, cell, org);

    CBrush frame(RGB(100, 100, 100));
    CBrush light(RGB(160, 160, 160));

    // 색 1 / 색 2 상자
    mem.FillSolidRect(rc1, m_color1);
    mem.FrameRect(rc1, &frame);
    mem.FillSolidRect(rc2, m_color2);
    mem.FrameRect(rc2, &frame);

    // 상자 아래 글자
    CFont* pFont = GetParent() ? GetParent()->GetFont() : nullptr;
    CFont* pOldFont = pFont ? mem.SelectObject(pFont) : nullptr;
    mem.SetBkMode(TRANSPARENT);
    mem.SetTextColor(GetSysColor(COLOR_BTNTEXT));
    CRect label1(rc1.left, labelTop, rc1.right, org.y);
    CRect label2(rc2.left, labelTop, rc2.right, org.y);
    mem.DrawText(_T("색 1"), label1, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
    mem.DrawText(_T("색 2"), label2, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
    if (pOldFont)
        mem.SelectObject(pOldFont);

    // 팔레트
    for (int i = 0; i < kPaletteCount; ++i)
    {
        CRect rc = PaletteCellRect(i);
        rc.DeflateRect(1, 1);
        mem.FillSolidRect(rc, m_palette[i]);
        mem.FrameRect(rc, &light);
    }

    dc.BitBlt(0, 0, client.Width(), client.Height(), &mem, 0, 0, SRCCOPY);
    mem.SelectObject(pOldBmp);
}

void CColorPanel::EditColor(COLORREF& color)
{
    CColorDialog dlg(color, CC_FULLOPEN | CC_RGBINIT, this);
    dlg.m_cc.lpCustColors = m_customColors;
    if (dlg.DoModal() == IDOK)
    {
        color = dlg.GetColor();
        NotifyChanged();
    }
}

void CColorPanel::NotifyChanged()
{
    Invalidate(FALSE);
    if (GetParent())
        GetParent()->SendMessage(WM_COLOR_PANEL_CHANGED);
}

void CColorPanel::OnLButtonDown(UINT /*nFlags*/, CPoint point)
{
    const int hit = HitTest(point);
    if (hit == HitColor1)
        EditColor(m_color1);
    else if (hit == HitColor2)
        EditColor(m_color2);
    else if (hit >= 0)
    {
        m_color1 = m_palette[hit];
        NotifyChanged();
    }
}

void CColorPanel::OnRButtonDown(UINT /*nFlags*/, CPoint point)
{
    const int hit = HitTest(point);
    if (hit >= 0)
    {
        m_color2 = m_palette[hit];
        NotifyChanged();
    }
}

