    ON_COMMAND(ID_EDIT_REDO_ACTION, &CMyPaintDlg::OnEditRedo)
    ON_CONTROL_RANGE(BN_CLICKED, IDC_TOOL_PENCIL, IDC_TOOL_ELLIPSE, &CMyPaintDlg::OnToolClicked)
    ON_CBN_SELCHANGE(IDC_SIZE_COMBO, &CMyPaintDlg::OnSizeComboChanged)
