    return true;
}

void CImageHistory::Clear()
{
    m_undo.clear();
    m_redo.clear();
    m_bytes = 0;
}

void CImageHistory::Trim()
{
    while (m_undo.size() > 1 && (m_undo.size() > m_maxDepth || m_bytes > m_maxBytes))
    {
        m_bytes -= m_undo.front().Bytes();
        m_undo.pop_front();
    }
}
