param([string]$Exe, [string]$Dir)
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Text;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public static class W {
  public delegate bool EnumProc(IntPtr h, IntPtr l);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc f, IntPtr l);
  [DllImport("user32.dll")] public static extern bool EnumChildWindows(IntPtr p, EnumProc f, IntPtr l);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetClassName(IntPtr h, StringBuilder sb, int n);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr h, StringBuilder sb, int n);
  [DllImport("user32.dll")] public static extern IntPtr GetDlgItem(IntPtr h, int id);
  [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr h, uint m, IntPtr w, IntPtr l);
  [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h, uint m, IntPtr w, IntPtr l);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool GetClientRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool MoveWindow(IntPtr h, int x, int y, int w, int hh, bool rp);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern uint GetDpiForWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h, IntPtr hdc, uint flags);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int L, T, R, B; }
  public static string Cls(IntPtr h) { var sb = new StringBuilder(256); GetClassName(h, sb, 256); return sb.ToString(); }
  public static string Txt(IntPtr h) { var sb = new StringBuilder(512); GetWindowText(h, sb, 512); return sb.ToString(); }
  public static List<IntPtr> Dialogs(uint pid, IntPtr exclude) {
    var list = new List<IntPtr>();
    EnumWindows((h, l) => { uint p; GetWindowThreadProcessId(h, out p);
      if (p == pid && h != exclude && IsWindowVisible(h) && Cls(h) == "#32770") list.Add(h); return true; }, IntPtr.Zero);
    return list;
  }
  public static string AllText(IntPtr p) {
    var sb = new StringBuilder();
    EnumChildWindows(p, (h, l) => { var t = Txt(h); if (t.Length > 0) sb.Append("[" + t + "]"); return true; }, IntPtr.Zero);
    return sb.ToString();
  }
}
"@
$shell = New-Object -ComObject WScript.Shell
$results = New-Object System.Collections.ArrayList
function Check($name, $ok, $detail='') { $null = $results.Add(("{0} {1} {2}" -f ($(if ($ok) {'PASS'} else {'FAIL'})), $name, $detail)) }
function MK([int]$x, [int]$y) { [IntPtr](($y -shl 16) -bor ($x -band 0xFFFF)) }
$WM_MOUSEMOVE=0x200; $WM_LBUTTONDOWN=0x201; $WM_LBUTTONUP=0x202; $WM_RBUTTONDOWN=0x204; $WM_RBUTTONUP=0x205; $WM_COMMAND=0x111
$MK_L=1; $MK_R=2; $MK_SHIFT=4

Get-ChildItem $Dir -Filter 't*.*' -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^t\d\.(png|bmp)$' } | Remove-Item
$p = Start-Process -FilePath $Exe -PassThru
Start-Sleep -Milliseconds 1500; $p.Refresh()
$h = $p.MainWindowHandle; $pid0 = [uint32]$p.Id
$canvas = [W]::GetDlgItem($h, 1030); $panel = [W]::GetDlgItem($h, 1021); $combo = [W]::GetDlgItem($h, 1011)

function Drag($down, $up, $flag, $pts) {
  [W]::SendMessage($canvas, $down, [IntPtr]$flag, (MK $pts[0][0] $pts[0][1])) | Out-Null
  foreach ($pt in $pts) { [W]::SendMessage($canvas, $WM_MOUSEMOVE, [IntPtr]$flag, (MK $pt[0] $pt[1])) | Out-Null }
  $upFlag = $flag -band $MK_SHIFT
  [W]::SendMessage($canvas, $up, [IntPtr]$upFlag, (MK $pts[-1][0] $pts[-1][1])) | Out-Null
}
function Tool([int]$id) { [W]::SendMessage($h, $WM_COMMAND, [IntPtr]$id, [W]::GetDlgItem($h, $id)) | Out-Null }
function Size([int]$lvl) { [W]::SendMessage($combo, 0x14E, [IntPtr]$lvl, [IntPtr]0) | Out-Null; [W]::SendMessage($h, $WM_COMMAND, [IntPtr]((1 -shl 16) -bor 1011), $combo) | Out-Null }
function PaletteClick([int]$idx, [uint32]$down) {
  $r = New-Object W+RECT; [W]::GetClientRect($panel, [ref]$r) | Out-Null
  $dpi = [W]::GetDpiForWindow($h); $gap = [int]([Math]::Round(4*$dpi/96)); $lab = [int]([Math]::Round(16*$dpi/96))
  $cell = [Math]::Min([int][Math]::Floor($r.R/4), [int][Math]::Floor(($r.B - $lab - $gap)/6))
  $x = ($idx % 4) * $cell + [int]($cell/2); $y = $cell + $lab + $gap + [int][Math]::Floor($idx/4) * $cell + [int]($cell/2)
  [W]::SendMessage($panel, $down, [IntPtr]0, (MK $x $y)) | Out-Null
}
function Shot($file) {
  $r = New-Object W+RECT; [W]::GetWindowRect($h, [ref]$r) | Out-Null
  $bmp = New-Object System.Drawing.Bitmap ($r.R - $r.L), ($r.B - $r.T)
  $g = [System.Drawing.Graphics]::FromImage($bmp); $hdc = $g.GetHdc(); [W]::PrintWindow($h, $hdc, 2) | Out-Null; $g.ReleaseHdc($hdc); $g.Dispose()
  $bmp.Save((Join-Path $Dir $file)); $bmp.Dispose()
}
function WaitDialog() { for ($i=0; $i -lt 40; $i++) { $d = [W]::Dialogs($pid0, $h); if ($d.Count -gt 0) { return $d[0] }; Start-Sleep -Milliseconds 150 }; return [IntPtr]::Zero }
function FileDialogType($path) {
  $d = WaitDialog; if ($d -eq [IntPtr]::Zero) { return $false }
  Start-Sleep -Milliseconds 700
  [W]::SetForegroundWindow($d) | Out-Null; Start-Sleep -Milliseconds 300
  $shell.SendKeys('^a'); Start-Sleep -Milliseconds 100
  $shell.SendKeys($path); Start-Sleep -Milliseconds 200
  $shell.SendKeys('{ENTER}')
  for ($i=0; $i -lt 40; $i++) { if (([W]::Dialogs($pid0, $h)).Count -eq 0) { return $true }; Start-Sleep -Milliseconds 150 }
  return $false
}
function Title() { [W]::Txt($h) }

# 1) Shift + 직선 → 수평선, Shift + 사각형 → 정사각형
Tool 1003; Size 1
Drag $WM_LBUTTONDOWN $WM_LBUTTONUP ($MK_L -bor $MK_SHIFT) @(@(40,40), @(200,55), @(300,70))
Tool 1004
Drag $WM_LBUTTONDOWN $WM_LBUTTONUP ($MK_L -bor $MK_SHIFT) @(@(330,40), @(380,100), @(420,140))
# 2) 빨강 직선 + 검정 사각형, 오른쪽 지우개로 검정만 흰색으로
PaletteClick 3 $WM_LBUTTONDOWN          # 색 1 = 빨강
Tool 1003; Size 2
Drag $WM_LBUTTONDOWN $WM_LBUTTONUP $MK_L @(@(20,205), @(260,205))
PaletteClick 0 $WM_LBUTTONDOWN          # 색 1 = 검정
Tool 1004; Size 3
Drag $WM_LBUTTONDOWN $WM_LBUTTONUP $MK_L @(@(40,160), @(200,250))
Tool 1002; Size 3
$pts = @(); for ($x=20; $x -le 260; $x+=3) { $pts += ,@($x, 205) }
Drag $WM_RBUTTONDOWN $WM_RBUTTONUP $MK_R $pts
# 3) 다른 버튼으로 취소: 왼쪽으로 타원 그리는 중 오른쪽 클릭
Tool 1005
[W]::SendMessage($canvas, $WM_LBUTTONDOWN, [IntPtr]1, (MK 500 300)) | Out-Null
[W]::SendMessage($canvas, $WM_MOUSEMOVE, [IntPtr]1, (MK 650 400)) | Out-Null
[W]::SendMessage($canvas, $WM_RBUTTONDOWN, [IntPtr]3, (MK 650 400)) | Out-Null
[W]::SendMessage($canvas, $WM_LBUTTONUP, [IntPtr]2, (MK 650 400)) | Out-Null
[W]::SendMessage($canvas, $WM_RBUTTONUP, [IntPtr]0, (MK 650 400)) | Out-Null
Start-Sleep -Milliseconds 300
Shot 'r1_draw.png'
Check 'modified title' ((Title) -like '`**') (Title)

# 4) 저장 (기본 PNG 필터, 확장자 없이 입력) → t1.png
$t1 = Join-Path $Dir 't1'
[W]::PostMessage($h, $WM_COMMAND, [IntPtr]32773, [IntPtr]0) | Out-Null
$ok = FileDialogType $t1
Start-Sleep -Milliseconds 500
Check 'save dialog closed' $ok
Check 'save png exists' (Test-Path "$t1.png")
Check 'title after save' ((Title) -eq 't1.png - MyPaint') (Title)
# 5) 다른 이름으로 저장 t2.bmp
[W]::PostMessage($h, $WM_COMMAND, [IntPtr]32774, [IntPtr]0) | Out-Null
$ok = FileDialogType (Join-Path $Dir 't2.bmp')
Start-Sleep -Milliseconds 500
Check 'save bmp exists' (Test-Path (Join-Path $Dir 't2.bmp'))
# 저장 파일 픽셀 검사
if (Test-Path "$t1.png") {
  $img = [System.Drawing.Bitmap]::FromFile("$t1.png")
  Check 'png size' ($img.Width -eq 800 -and $img.Height -eq 600) "$($img.Width)x$($img.Height)"
  # 이미지 좌표 = 클라이언트 좌표 - 여백 5
  $c = $img.GetPixel(150-5, 40-5);   Check 'shift line horizontal (y=35 black)' ($c.R -lt 50 -and $c.G -lt 50) "$c"
  $c = $img.GetPixel(290-5, 41-5);   Check 'shift line end stays at y=35' ($img.GetPixel(290-5,40-5).R -lt 50) "$c"
  $c = $img.GetPixel(330-5+50, 140-5); Check 'shift rect is square (no edge at y=135)' ($c.R -gt 200 -and $c.G -gt 200) "$c"
  $c = $img.GetPixel(330-5+50, 140-5+1+9); Check 'shift rect bottom edge at y=145 (d=100)' ($c.R -lt 50) "$c"
  $c = $img.GetPixel(41-5, 180-5);   Check 'rect left edge black (outside eraser path)' ($c.R -lt 50) "$c"
  $c = $img.GetPixel(41-5, 205-5);   Check 'right-eraser: black on path -> red/white' (-not ($c.R -lt 50 -and $c.G -lt 50)) "$c"
  $c = $img.GetPixel(120-5, 205-5);  Check 'right-eraser: red line kept' ($c.R -gt 200 -and $c.G -lt 60) "$c"
  $c = $img.GetPixel(575-5, 350-5);  Check 'cancelled ellipse not drawn' ($c.R -gt 200 -and $c.G -gt 200 -and $c.B -gt 200) "$c"
  $img.Dispose()
}
# 6) 새로 만들기 → 저장 안 된 변경 없음 → 질문 없이 비워짐
[W]::PostMessage($h, $WM_COMMAND, [IntPtr]32771, [IntPtr]0) | Out-Null
Start-Sleep -Milliseconds 600
Check 'new without prompt' (([W]::Dialogs($pid0, $h)).Count -eq 0 -and (Title) -eq '제목 없음 - MyPaint') (Title)
# 7) 열기 t1.png
[W]::PostMessage($h, $WM_COMMAND, [IntPtr]32772, [IntPtr]0) | Out-Null
$ok = FileDialogType "$t1.png"
Start-Sleep -Milliseconds 600
Check 'open title' ((Title) -eq 't1.png - MyPaint') (Title)
Shot 'r2_open.png'
# 8) 스크롤: 창을 줄이고 오른쪽 아래 끝으로
[W]::MoveWindow($h, 50, 50, 700, 560, $true) | Out-Null
Start-Sleep -Milliseconds 300
[W]::SendMessage($canvas, 0x115, [IntPtr]7, [IntPtr]0) | Out-Null  # WM_VSCROLL SB_BOTTOM
[W]::SendMessage($canvas, 0x114, [IntPtr]7, [IntPtr]0) | Out-Null  # WM_HSCROLL SB_BOTTOM
Start-Sleep -Milliseconds 300
Shot 'r3_scroll.png'
# 9) 수정 후 닫기 → 저장 질문 → 아니요
Tool 1001
Drag $WM_LBUTTONDOWN $WM_LBUTTONUP $MK_L @(@(100,100), @(200,200))
[W]::PostMessage($h, 0x10, [IntPtr]0, [IntPtr]0) | Out-Null  # WM_CLOSE
