506	void CCanvasWnd::DrawStrokeSegment(CDC& dc, CPoint from, CPoint to, COLORREF color) const
507	{
508	    const int width = CurrentWidth();
509	    if (width <= 1)
510	    {
511	        CPen pen(PS_SOLID, 1, color);
512	        CPen* pOld = dc.SelectObject(&pen);
513	        dc.MoveTo(from);
514	        dc.LineTo(to);
515	        dc.SelectObject(pOld);
516	        dc.SetPixelV(to, color); // LineTo는 끝점을 그리지 않음
517	        return;
518	    }
