                    if ((row[x] & 0x00FFFFFF) == target)
                        row[x] = replacement;
                }
            }
        }
        dirty.UnionRect(dirty, rc);
    }
    return dirty;
}

void CCanvasWnd::BeginFreehand(DragButton button, CPoint imgPt)
{
    m_beforeDrag = CaptureSnapshot();
    BeginDrag(DragMode::Freehand, button, imgPt);

    // 누른 자리에 바로 점을 찍습니다.
    HDC hdc = m_image.GetDC();
    CDC* pDC = CDC::FromHandle(hdc);
    CRect dirty;
    if (m_tool == ToolType::Eraser)
    {
        dirty = EraseSegment(*pDC, imgPt, imgPt);
    }
    else
    {
        DrawStrokeSegment(*pDC, imgPt, imgPt, DragColor());
        dirty = CRect(imgPt, imgPt);
        dirty.InflateRect(CurrentWidth(), CurrentWidth());
    }
    m_image.ReleaseDC();
    InvalidateImageRect(dirty);
}

void CCanvasWnd::ContinueFreehand(CPoint imgPt)
{
    if (imgPt == m_dragLast)
        return;

    HDC hdc = m_image.GetDC();
    CDC* pDC = CDC::FromHandle(hdc);
    CRect dirty;
    if (m_tool == ToolType::Eraser)
    {
        dirty = EraseSegment(*pDC, m_dragLast, imgPt);
    }
    else
    {
        DrawStrokeSegment(*pDC, m_dragLast, imgPt, DragColor());
        dirty = CRect(m_dragLast, imgPt);
        dirty.NormalizeRect();
        dirty.InflateRect(CurrentWidth(), CurrentWidth());
    }
    m_image.ReleaseDC();
    InvalidateImageRect(dirty);
}

// ---------------------------------------------------------------------------
// 도형 (미리 보기 이미지)
// ---------------------------------------------------------------------------
//
// 확대 상태에서도 확정 결과와 픽셀 단위로 똑같이 보이도록, 화면 위에 따로 그리지 않고
// m_image의 사본(m_preview)에 도형을 그려 그 사본을 보여 줍니다.
// 마우스가 움직일 때마다 이전 도형이 있던 영역만 m_image에서 다시 복사해 지웁니다.

CRect CCanvasWnd::ShapeBounds(CPoint start, CPoint end) const
{
    CRect rc(start, end);
    rc.NormalizeRect();
    rc.InflateRect(CurrentWidth() + 2, CurrentWidth() + 2);
    return rc;
}

void CCanvasWnd::BeginShape(DragButton button, CPoint imgPt)
{
    const CSize size = GetImageSize();
    if (!CreateDib32(m_preview, size.cx, size.cy, RGB(255, 255, 255)))
        return;
    HDC hdc = m_preview.GetDC();
    m_image.BitBlt(hdc, 0, 0);
    m_preview.ReleaseDC();

    BeginDrag(DragMode::Shape, button, imgPt);
    UpdateShapePreview(imgPt);
}

void CCanvasWnd::UpdateShapePreview(CPoint end)
{
    if (m_preview.IsNull())
        return;

    const CRect oldBox = ShapeBounds(m_dragStart, m_dragCurrent);
    m_dragCurrent = end;
    const CRect newBox = ShapeBounds(m_dragStart, end);

    HDC hdc = m_preview.GetDC();
    CRect restore;
    if (restore.IntersectRect(oldBox, ImageBounds()))
        m_image.BitBlt(hdc, restore.left, restore.top, restore.Width(), restore.Height(), restore.left, restore.top);
    DrawShape(*CDC::FromHandle(hdc), m_dragStart, end, DragColor());
    m_preview.ReleaseDC();

    CRect dirty;
    dirty.UnionRect(oldBox, newBox);
    InvalidateImageRect(dirty);
}

void CCanvasWnd::CommitShape(CPoint end)
{
    m_dragCurrent = end;
    ImageSnapshot before = CaptureSnapshot();

    HDC hdc = m_image.GetDC();
    DrawShape(*CDC::FromHandle(hdc), m_dragStart, end, DragColor());
    m_image.ReleaseDC();

    m_history.Push(std::move(before));
    m_preview.Destroy();
    MarkModified();
}

CPoint CCanvasWnd::ConstrainShapeEnd(CPoint start, CPoint end, bool shift) const
{
    if (!shift)
        return end;

    const int dx = end.x - start.x;
    const int dy = end.y - start.y;
    const int adx = std::abs(dx);
    const int ady = std::abs(dy);
    const int sx = dx < 0 ? -1 : 1;
    const int sy = dy < 0 ? -1 : 1;

    if (m_tool == ToolType::Line)
    {
        // 0°, 45°, 90° 중 가까운 방향으로 고정 (tan 22.5° ≈ 0.414)
        if (ady * 1000 < adx * 414)
            return CPoint(end.x, start.y);
        if (adx * 1000 < ady * 414)
            return CPoint(start.x, end.y);
    }

    // 정사각형/정원 또는 45° 대각선
    const int d = std::max(adx, ady);
    return CPoint(start.x + sx * d, start.y + sy * d);
}

void CCanvasWnd::DrawShape(CDC& dc, CPoint start, CPoint end, COLORREF color) const
{
    if (m_tool == ToolType::Line)
    {
        DrawStrokeSegment(dc, start, end, color);
        return;
    }

    CRect rc(start, end);
    rc.NormalizeRect();
    rc.right += 1; // 드래그한 끝 픽셀까지 포함
    rc.bottom += 1;

    // PS_INSIDEFRAME: 굵기가 두꺼워도 선이 드래그한 사각형 안쪽에 그려짐
    CPen pen(PS_INSIDEFRAME, CurrentWidth(), color);
    CPen* pOldPen = dc.SelectObject(&pen);
    CGdiObject* pOldBrush = dc.SelectStockObject(NULL_BRUSH);
    if (m_tool == ToolType::Rectangle)
        dc.Rectangle(rc);
    else
        dc.Ellipse(rc);
    dc.SelectObject(pOldBrush);
    dc.SelectObject(pOldPen);
}

// ---------------------------------------------------------------------------
// 채우기 / 스포이트
// ---------------------------------------------------------------------------

void CCanvasWnd::DoFill(CPoint imgPt, COLORREF color)
{
    if (!IsInImage(imgPt))
        return;

    GdiFlush();
    const CSize size = GetImageSize();
    auto* base = static_cast<BYTE*>(m_image.GetPixelAddress(0, 0));
    const uint32_t fill = ToPixel(color);
    if ((static_cast<uint32_t*>(m_image.GetPixelAddress(imgPt.x, imgPt.y))[0] & 0x00FFFFFF) == fill)
        return; // 이미 같은 색: 기록을 남기지 않음

    ImageSnapshot before = CaptureSnapshot();
    ScanlineFill(base, m_image.GetPitch(), size.cx, size.cy, imgPt.x, imgPt.y, fill);
    m_history.Push(std::move(before));
    Invalidate(FALSE);
    MarkModified();
}

void CCanvasWnd::DoPick(CPoint imgPt, DragButton button)
{
    if (!IsInImage(imgPt))
        return;

    GdiFlush();
    const uint32_t pixel = static_cast<uint32_t*>(m_image.GetPixelAddress(imgPt.x, imgPt.y))[0];
    NotifyParent(button == DragButton::Right ? CN_PICK_COLOR2 : CN_PICK_COLOR1, static_cast<LPARAM>(ToColor(pixel)));

    // Windows 그림판처럼 색을 고르면 직전 도구로 돌아갑니다.
    ChangeToolInternal(m_toolBeforePicker);
}

