/**
 * @file CanvasSelection.cpp
 * @brief 캔버스 선택 영역: 사각형 선택, 이동/복사, 클립보드
 *
 * 선택 영역에는 두 가지 상태가 있습니다.
 * - 고정: 이미지 위에 테두리만 있는 상태 (m_floating == false)
 * - 떠 있음: 선택한 그림을 떼어 m_floatImage로 들고 있는 상태. 이동하거나 붙여넣으면 이 상태가 됩니다.
 *   다른 곳을 클릭하거나 도구를 바꾸면 그 자리에 찍히며(확정) 선택이 끝납니다.
 *
 * 실행 취소 기록은 떼어 낼 때(또는 붙여넣을 때) 한 번만 남기므로,
 * 이동하고 확정한 뒤 실행 취소하면 이동 전 상태로 한 번에 돌아갑니다.
 */
#include "pch.h"
#include "CanvasWnd.h"
#include "CanvasInternal.h"

#ifdef _DEBUG
#define new DEBUG_NEW
#endif

using namespace canvas;

CRect CCanvasWnd::SelectionFromDrag(CPoint a, CPoint b) const
{
    CRect rc(a, b);
    rc.NormalizeRect();
    rc.right += 1; // 끝 픽셀까지 포함
    rc.bottom += 1;
    rc.IntersectRect(rc, ImageBounds());
    return rc;
}

void CCanvasWnd::LiftSelection(bool copy)
{
    if (m_floating || !m_hasSelection)
        return;

    if (!CreateDib32(m_floatImage, m_selRect.Width(), m_selRect.Height(), RGB(255, 255, 255)))
        return;
    m_history.Push(CaptureSnapshot());

    HDC hdc = m_floatImage.GetDC();
    m_image.BitBlt(hdc, 0, 0, m_selRect.Width(), m_selRect.Height(), m_selRect.left, m_selRect.top);
    m_floatImage.ReleaseDC();

    if (!copy)
    {
        // 옮기면 원래 자리는 배경색(색 2)으로 비움
        hdc = m_image.GetDC();
        CDC::FromHandle(hdc)->FillSolidRect(m_selRect, m_color2);
        m_image.ReleaseDC();
    }
    m_floating = true;
    MarkModified();
}

void CCanvasWnd::StampFloating()
{
    if (!m_floating || m_floatImage.IsNull())
        return;
    HDC hdc = m_image.GetDC();
    m_floatImage.BitBlt(hdc, m_selRect.left, m_selRect.top); // 이미지 밖으로 나간 부분은 잘림
    m_image.ReleaseDC();
}

void CCanvasWnd::BeginMoveSelection(CPoint imgPt, bool copy)
{
