    if (!ReadClipboard(clip))
        return false;

    ChangeToolInternal(ToolType::Select); // 진행 중인 작업 확정 후 선택 도구로

    ImageSnapshot before = CaptureSnapshot();
    const CSize size = GetImageSize();
    if (clip.GetWidth() > size.cx || clip.GetHeight() > size.cy)
    {
        const int answer = MessageBox(
            _T("붙여넣는 그림이 캔버스보다 큽니다.\n캔버스를 그림 크기에 맞게 늘릴까요?"),
            _T("MyPaint"), MB_YESNOCANCEL | MB_ICONQUESTION);
        if (answer == IDCANCEL)
            return false;
        if (answer == IDYES)
            ResizeCanvasTo(CSize(std::max<int>(size.cx, clip.GetWidth()), std::max<int>(size.cy, clip.GetHeight())), false);
    }
    m_history.Push(std::move(before)); // 캔버스 늘리기와 붙여넣기를 한 단계로

    // 지금 화면에 보이는 영역의 왼쪽 위에 붙여넣습니다.
    CPoint topLeft = ClientToImage(CPoint(0, 0));
    topLeft.x = std::max<int>(0, topLeft.x);
    topLeft.y = std::max<int>(0, topLeft.y);

    m_selRect = CRect(topLeft, CSize(clip.GetWidth(), clip.GetHeight()));
    ReplaceImage(m_floatImage, clip);
    m_floating = true;
    m_hasSelection = true;
    Invalidate(FALSE);
    NotifySelectionSize();
    MarkModified();
    return true;
}

// ---------------------------------------------------------------------------
// 클립보드
// ---------------------------------------------------------------------------

bool CCanvasWnd::WriteClipboard(CImage& source, const CRect& rect)
{
    // 대부분의 프로그램이 읽을 수 있는 24비트 CF_DIB(아래→위 순서)로 올립니다.
    const int width = rect.Width();
    const int height = rect.Height();
    if (width <= 0 || height <= 0)
        return false;

    const int stride = (width * 3 + 3) & ~3;
    const size_t bytes = sizeof(BITMAPINFOHEADER) + static_cast<size_t>(stride) * height;
    HGLOBAL hMem = ::GlobalAlloc(GMEM_MOVEABLE, bytes);
    if (!hMem)
        return false;

    auto* bih = static_cast<BITMAPINFOHEADER*>(::GlobalLock(hMem));
    ZeroMemory(bih, sizeof(BITMAPINFOHEADER));
    bih->biSize = sizeof(BITMAPINFOHEADER);
    bih->biWidth = width;
    bih->biHeight = height; // 양수: 아래→위
    bih->biPlanes = 1;
    bih->biBitCount = 24;
    bih->biCompression = BI_RGB;
    bih->biSizeImage = static_cast<DWORD>(stride) * height;

    GdiFlush();
    BYTE* bits = reinterpret_cast<BYTE*>(bih + 1);
    for (int y = 0; y < height; ++y)
    {
        const auto* src = static_cast<const uint32_t*>(source.GetPixelAddress(rect.left, rect.top + y));
        BYTE* dst = bits + static_cast<size_t>(height - 1 - y) * stride;
        for (int x = 0; x < width; ++x)
        {
            dst[x * 3 + 0] = static_cast<BYTE>(src[x] & 0xFF);         // B
            dst[x * 3 + 1] = static_cast<BYTE>((src[x] >> 8) & 0xFF);  // G
            dst[x * 3 + 2] = static_cast<BYTE>((src[x] >> 16) & 0xFF); // R
        }
    }
    ::GlobalUnlock(hMem);

    if (!OpenClipboard())
    {
        ::GlobalFree(hMem);
        return false;
    }
    ::EmptyClipboard();
    const bool ok = ::SetClipboardData(CF_DIB, hMem) != nullptr;
    ::CloseClipboard();
    if (!ok)
        ::GlobalFree(hMem); // 성공하면 메모리는 클립보드 소유
    return ok;
}

bool CCanvasWnd::ReadClipboard(CImage& out)
{
    if (!CanPaste() || !OpenClipboard())
        return false;

    // CF_DIB만 있어도 시스템이 CF_BITMAP을 만들어 주므로 CF_BITMAP 하나로 읽습니다.
    bool ok = false;
    auto hBitmap = static_cast<HBITMAP>(::GetClipboardData(CF_BITMAP));
    BITMAP bm{};
    if (hBitmap && ::GetObject(hBitmap, sizeof(bm), &bm) && bm.bmWidth > 0 && bm.bmHeight > 0
        && CreateDib32(out, bm.bmWidth, bm.bmHeight, RGB(255, 255, 255)))
    {
        CDC src;
        src.CreateCompatibleDC(nullptr);
        HGDIOBJ old = ::SelectObject(src.GetSafeHdc(), hBitmap);
        HDC hdc = out.GetDC();
        ::BitBlt(hdc, 0, 0, bm.bmWidth, bm.bmHeight, src.GetSafeHdc(), 0, 0, SRCCOPY);
        out.ReleaseDC();
        ::SelectObject(src.GetSafeHdc(), old); // 클립보드 소유 비트맵이므로 삭제하지 않음
        ok = true;
    }
    ::CloseClipboard();
    return ok;
}

