        HGDIOBJ old = ::SelectObject(src.GetSafeHdc(), hBitmap);
        HDC hdc = out.GetDC();
        ::BitBlt(hdc, 0, 0, bm.bmWidth, bm.bmHeight, src.GetSafeHdc(), 0, 0, SRCCOPY);
        out.ReleaseDC();
        ::SelectObject(src.GetSafeHdc(), old); // 클립보드 소유 비트맵이므로 삭제하지 않음
        ok = true;
    }
    ::CloseClipboard();
    return ok;
