{
    m_hIcon = AfxGetApp()->LoadIcon(IDR_MAINFRAME);
}

void CMyPaintDlg::DoDataExchange(CDataExchange* pDX)
{
    CDialog::DoDataExchange(pDX);
    DDX_Control(pDX, IDC_SIZE_COMBO, m_sizeCombo);
}

BOOL CMyPaintDlg::OnInitDialog()
{
    CDialog::OnInitDialog();

    SetIcon(m_hIcon, TRUE);  // 큰 아이콘
    SetIcon(m_hIcon, FALSE); // 작은 아이콘

    m_hAccel = ::LoadAccelerators(AfxGetResourceHandle(), MAKEINTRESOURCE(IDR_ACCEL));

    m_colorPanel.SubclassDlgItem(IDC_COLOR_PANEL, this);
    m_statusBar.Create(WS_CHILD | WS_VISIBLE | SBARS_SIZEGRIP, CRect(0, 0, 0, 0), this, IDC_STATUSBAR);
    m_canvas.Create(this, IDC_CANVAS);

    m_canvas.SetTool(ToolType::Pencil);
    m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
    SyncToolUi();

    m_canvas.NewImage(kDefaultWidth, kDefaultHeight);

    LayoutControls();
    UpdateTitle();
    UpdateStatusImageSize();
    UpdateStatusZoom();

    m_canvas.SetFocus();
    return FALSE; // 포커스를 직접 지정했음
}

BOOL CMyPaintDlg::PreTranslateMessage(MSG* pMsg)
{
    // 대화 상자는 단축키 테이블을 자동으로 처리하지 않으므로 직접 변환합니다.
    // 단, 글상자에 입력 중일 때는 Ctrl+C/V/Z, Del 등을 편집 컨트롤이 쓰도록 넘깁니다.
    if (m_hAccel && pMsg->message >= WM_KEYFIRST && pMsg->message <= WM_KEYLAST
        && !m_canvas.IsTextEditWindow(pMsg->hwnd)
        && ::TranslateAccelerator(m_hWnd, m_hAccel, pMsg))
    {
        return TRUE;
    }
    return CDialog::PreTranslateMessage(pMsg);
}

void CMyPaintDlg::OnOK()
{
    // Enter 키로 닫히지 않게 함
}

void CMyPaintDlg::OnCancel()
{
    // Esc 키로 닫히지 않게 함. 창 닫기는 OnClose에서 처리합니다.
    m_canvas.CancelOperation();
}

void CMyPaintDlg::OnClose()
{
    if (ConfirmDiscardChanges())
        EndDialog(IDCANCEL);
}

// ---------------------------------------------------------------------------
// 배치
// ---------------------------------------------------------------------------

void CMyPaintDlg::LayoutControls()
{
    if (!m_canvas.GetSafeHwnd() || !m_statusBar.GetSafeHwnd())
        return;

    CRect client;
    GetClientRect(&client);

    int canvasBottom = client.bottom;
    if (m_statusVisible)
    {
        // 상태 표시줄은 WM_SIZE를 받으면 스스로 아래쪽에 붙습니다.
        m_statusBar.SendMessage(WM_SIZE);
        CRect rcStatus;
        m_statusBar.GetWindowRect(&rcStatus);
        ScreenToClient(&rcStatus);
        canvasBottom = rcStatus.top;

        const int dpi = static_cast<int>(GetDpiForWindow(m_hWnd));
        int parts[SP_COUNT] = {};
        const int widths[SP_COUNT - 1] = { 110, 110, 110, 70 };
        int x = 0;
        for (int i = 0; i < SP_COUNT - 1; ++i)
        {
            x += MulDiv(widths[i], dpi, 96);
            parts[i] = x;
        }
        parts[SP_HINT] = -1;
        m_statusBar.SetParts(SP_COUNT, parts);
    }

    // 캔버스는 도구 패널 오른쪽부터 상태 표시줄 위까지 채웁니다.
    CRect rcGroup;
    GetDlgItem(IDC_TOOL_GROUP)->GetWindowRect(&rcGroup);
    ScreenToClient(&rcGroup);
    const int left = rcGroup.right + rcGroup.left;
    m_canvas.MoveWindow(left, 0, std::max<int>(0, client.right - left), std::max(0, canvasBottom));
}

void CMyPaintDlg::OnSize(UINT nType, int cx, int cy)
{
    CDialog::OnSize(nType, cx, cy);
    if (nType != SIZE_MINIMIZED)
        LayoutControls();
}

BOOL CMyPaintDlg::OnEraseBkgnd(CDC* pDC)
{
    // 캔버스 영역은 캔버스가 직접 그리므로 지우지 않습니다. (크기 조절 시 깜박임 방지)
    if (m_canvas.GetSafeHwnd())
    {
        CRect rc;
        m_canvas.GetWindowRect(&rc);
        ScreenToClient(&rc);
        pDC->ExcludeClipRect(rc);
    }
    return CDialog::OnEraseBkgnd(pDC);
}

void CMyPaintDlg::OnGetMinMaxInfo(MINMAXINFO* lpMMI)
{
    CDialog::OnGetMinMaxInfo(lpMMI);
    if (!GetSafeHwnd() || !m_colorPanel.GetSafeHwnd())
        return;

    // 왼쪽 패널(색 패널 아래 끝)이 잘리지 않을 만큼의 높이를 최소 크기로
    const int dpi = static_cast<int>(GetDpiForWindow(m_hWnd));
    CRect rcPanel;
    m_colorPanel.GetWindowRect(&rcPanel);
    ScreenToClient(&rcPanel);
    int clientHeight = rcPanel.bottom + MulDiv(8, dpi, 96);
    if (m_statusVisible && m_statusBar.GetSafeHwnd())
    {
        CRect rcStatus;
        m_statusBar.GetWindowRect(&rcStatus);
        clientHeight += rcStatus.Height();
    }
    CRect rc(0, 0, MulDiv(640, dpi, 96), clientHeight);
    AdjustWindowRectEx(&rc, GetStyle(), TRUE, GetExStyle());
    lpMMI->ptMinTrackSize.x = rc.Width();
    lpMMI->ptMinTrackSize.y = rc.Height();
}

void CMyPaintDlg::OnInitMenuPopup(CMenu* pPopupMenu, UINT nIndex, BOOL bSysMenu)
{
    CDialog::OnInitMenuPopup(pPopupMenu, nIndex, bSysMenu);
    if (bSysMenu)
        return;

    // 대화 상자에는 ON_UPDATE_COMMAND_UI가 동작하지 않으므로 직접 켜고 끕니다.
    auto enable = [&](UINT id, bool on) {
        pPopupMenu->EnableMenuItem(id, MF_BYCOMMAND | (on ? MF_ENABLED : MF_GRAYED));
    };
    const bool hasSel = m_canvas.HasSelection();
    enable(ID_EDIT_UNDO_ACTION, m_canvas.CanUndo());
    enable(ID_EDIT_REDO_ACTION, m_canvas.CanRedo());
    enable(ID_EDIT_CUT_SEL, hasSel);
    enable(ID_EDIT_COPY_SEL, hasSel);
    enable(ID_EDIT_DELETE_SEL, hasSel);
    enable(ID_EDIT_PASTE_IMG, CCanvasWnd::CanPaste());
    pPopupMenu->CheckMenuItem(ID_VIEW_STATUSBAR, MF_BYCOMMAND | (m_statusVisible ? MF_CHECKED : MF_UNCHECKED));
}

// ---------------------------------------------------------------------------
// 상태 표시
// ---------------------------------------------------------------------------

CString CMyPaintDlg::DisplayName() const
{
    if (m_filePath.IsEmpty())
        return _T("제목 없음");
    return m_filePath.Mid(m_filePath.ReverseFind(_T('\\')) + 1);
}

void CMyPaintDlg::UpdateTitle()
{
    CString title;
    title.Format(_T("%s%s - MyPaint"), m_canvas.IsModified() ? _T("*") : _T(""), DisplayName().GetString());
    SetWindowText(title);
}

void CMyPaintDlg::UpdateStatusImageSize()
{
    if (!m_statusBar.GetSafeHwnd())
        return;
    const CSize size = m_canvas.GetImageSize();
    CString text;
    text.Format(_T("%d × %dpx"), size.cx, size.cy);
    m_statusBar.SetText(text, SP_IMAGE, 0);
}

void CMyPaintDlg::UpdateStatusZoom()
{
    if (!m_statusBar.GetSafeHwnd())
        return;
    CString text;
    text.Format(_T("%g%%"), m_canvas.GetZoom() * 100.0);
    m_statusBar.SetText(text, SP_ZOOM, 0);
}

void CMyPaintDlg::UpdateHint()
{
    if (!m_statusBar.GetSafeHwnd())
        return;

    CString hint;
    switch (m_canvas.GetTool())
    {
    case ToolType::Pencil:
        hint = _T("왼쪽 버튼: 색 1 · 오른쪽 버튼: 색 2 · Esc: 취소");
        break;
    case ToolType::Eraser:
        hint = _T("왼쪽: 색 2로 지우기 · 오른쪽: 색 1인 부분만 색 2로 바꾸기");
        break;
    case ToolType::Fill:
        hint = _T("왼쪽: 색 1로 채우기 · 오른쪽: 색 2로 채우기");
        break;
    case ToolType::Picker:
        hint = _T("왼쪽: 색 1로 지정 · 오른쪽: 색 2로 지정 (지정 후 직전 도구로 돌아감)");
        break;
    case ToolType::Text:
    {
        LOGFONT lf;
        int pt = 0;
        m_canvas.GetTextFont(lf, pt);
        hint.Format(_T("드래그/클릭: 글상자 · 바깥 클릭: 확정 · Esc: 취소 · 글꼴: %s %dpt"), lf.lfFaceName, pt);
        break;
    }
    case ToolType::Select:
        hint = _T("드래그: 선택 · 안쪽 드래그: 이동 (Ctrl: 복사) · 방향키: 1px 이동 · Del: 삭제 · Esc: 확정");
        break;
    default:
        hint = _T("왼쪽 버튼: 색 1 · 오른쪽 버튼: 색 2 · Shift: 정사각형/정원/45° · Esc: 취소");
        break;
    }
    m_statusBar.SetText(hint, SP_HINT, 0);
}

void CMyPaintDlg::SyncToolUi()
{
    const ToolType tool = m_canvas.GetTool();
    CheckRadioButton(IDC_TOOL_PENCIL, IDC_TOOL_ELLIPSE, IDC_TOOL_PENCIL + static_cast<int>(tool));

    // 굵기 목록을 현재 도구의 픽셀 값으로 다시 채움
    const int level = m_canvas.GetSizeLevel();
    m_sizeCombo.ResetContent();
    for (int i = 0; i < kSizeLevelCount; ++i)
    {
        CString text;
        text.Format(_T("%d px"), CCanvasWnd::GetToolWidth(tool, i));
        m_sizeCombo.AddString(text);
    }
    m_sizeCombo.SetCurSel(level);
    const BOOL usesSize = CCanvasWnd::ToolUsesSize(tool) ? TRUE : FALSE;
    m_sizeCombo.EnableWindow(usesSize);
    GetDlgItem(IDC_SIZE_LABEL)->EnableWindow(usesSize);

    UpdateHint();
}

LRESULT CMyPaintDlg::OnCanvasNotify(WPARAM wParam, LPARAM lParam)
{
    switch (wParam)
    {
    case CN_CURSOR:
    case CN_SELSIZE:
        if (m_statusBar.GetSafeHwnd())
        {
            CString text;
            if (lParam != -1)
            {
                text.Format(wParam == CN_CURSOR ? _T("%d, %dpx") : _T("%d × %dpx"),
                            LOWORD(lParam), HIWORD(lParam));
            }
            m_statusBar.SetText(text, wParam == CN_CURSOR ? SP_CURSOR : SP_SELECTION, 0);
        }
        break;
    case CN_STATE:
        UpdateTitle();
        UpdateStatusImageSize();
        break;
    case CN_ZOOM:
        UpdateStatusZoom();
        break;
    case CN_TOOL:
        SyncToolUi();
        break;
    case CN_PICK_COLOR1:
        m_colorPanel.SetColor1(static_cast<COLORREF>(lParam));
        m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
        break;
    case CN_PICK_COLOR2:
        m_colorPanel.SetColor2(static_cast<COLORREF>(lParam));
        m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
        break;
    }
    return 0;
}

LRESULT CMyPaintDlg::OnColorPanelChanged(WPARAM /*wParam*/, LPARAM /*lParam*/)
{
    m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
    m_canvas.FocusTextEdit(); // 글상자 입력 중이었다면 계속 입력할 수 있게
    return 0;
}

// ---------------------------------------------------------------------------
// 도구
// ---------------------------------------------------------------------------

void CMyPaintDlg::OnToolClicked(UINT nID)
{
    static_assert(IDC_TOOL_ELLIPSE - IDC_TOOL_PENCIL == static_cast<int>(ToolType::Ellipse),
                  "도구 버튼 ID 순서와 ToolType 순서가 같아야 합니다.");
    m_canvas.SetTool(static_cast<ToolType>(nID - IDC_TOOL_PENCIL));
    SyncToolUi();
    m_canvas.SetFocus();
}

void CMyPaintDlg::OnSizeComboChanged()
{
    const int sel = m_sizeCombo.GetCurSel();
    if (sel != CB_ERR)
        m_canvas.SetSizeLevel(sel);
}

void CMyPaintDlg::OnTextFont()
{
    LOGFONT lf;
    int pointSize = 0;
    m_canvas.GetTextFont(lf, pointSize);

    // 글꼴 대화 상자는 화면 DPI 기준 높이를 받으므로 포인트 크기를 변환해서 넘깁니다.
    CClientDC dc(this);
    lf.lfHeight = -MulDiv(pointSize, dc.GetDeviceCaps(LOGPIXELSY), 72);

    CFontDialog dlg(&lf, CF_SCREENFONTS | CF_EFFECTS | CF_INITTOLOGFONTSTRUCT, nullptr, this);
    dlg.m_cf.rgbColors = m_colorPanel.GetColor1();
    if (dlg.DoModal() == IDOK)
    {
        LOGFONT chosen;
        dlg.GetCurrentFont(&chosen);
        m_canvas.SetTextFont(chosen, std::max(1, dlg.GetSize() / 10));

        // 글꼴 대화 상자에서 고른 색은 색 1로
        m_colorPanel.SetColor1(dlg.GetColor());
        m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
        UpdateHint();
    }
    m_canvas.FocusTextEdit();
}

void CMyPaintDlg::OnTextTransparent()
{
    m_canvas.SetTextTransparent(IsDlgButtonChecked(IDC_TEXT_TRANSPARENT) == BST_CHECKED);
    m_canvas.FocusTextEdit();
}

// ---------------------------------------------------------------------------
// 편집 / 보기
// ---------------------------------------------------------------------------

void CMyPaintDlg::OnEditUndo()
{
    m_canvas.Undo();
}

void CMyPaintDlg::OnEditRedo()
{
    m_canvas.Redo();
}

void CMyPaintDlg::OnEditCut()
{
    m_canvas.CutSelection();
}

void CMyPaintDlg::OnEditCopy()
{
    m_canvas.CopySelection();
}

void CMyPaintDlg::OnEditPaste()
{
    m_canvas.Paste();
    m_canvas.SetFocus();
}

void CMyPaintDlg::OnEditDelete()
{
    m_canvas.DeleteSelection();
}

void CMyPaintDlg::OnEditSelectAll()
{
    m_canvas.SelectAll();
    m_canvas.SetFocus();
}

void CMyPaintDlg::OnViewZoomIn()
{
    m_canvas.ZoomIn();
}

void CMyPaintDlg::OnViewZoomOut()
{
    m_canvas.ZoomOut();
}

void CMyPaintDlg::OnViewZoom100()
{
    m_canvas.SetZoom(1.0);
}

void CMyPaintDlg::OnViewStatusBar()
{
    m_statusVisible = !m_statusVisible;
    m_statusBar.ShowWindow(m_statusVisible ? SW_SHOW : SW_HIDE);
    LayoutControls();
}

// ---------------------------------------------------------------------------
// 파일
// ---------------------------------------------------------------------------

bool CMyPaintDlg::ConfirmDiscardChanges()
{
    m_canvas.FinishPendingWork(); // 입력 중인 글, 떠 있는 선택 영역도 변경 내용에 포함
    if (!m_canvas.IsModified())
        return true;

    CString msg;
    msg.Format(_T("변경 내용을 %s에 저장하시겠습니까?"), DisplayName().GetString());
    switch (MessageBox(msg, _T("MyPaint"), MB_YESNOCANCEL | MB_ICONWARNING))
    {
    case IDYES:
        return m_filePath.IsEmpty() ? SaveAsWithDialog() : SaveTo(m_filePath);
    case IDNO:
        return true;
    default:
        return false;
    }
}

bool CMyPaintDlg::SaveTo(const CString& path)
{
    const HRESULT hr = m_canvas.SaveToFile(path);
    if (FAILED(hr))
    {
        CString msg;
        msg.Format(_T("파일을 저장하지 못했습니다.\n%s\n\n지원 형식: PNG, BMP, JPEG, GIF, TIFF (오류 코드 0x%08X)"),
                   path.GetString(), static_cast<unsigned>(hr));
        MessageBox(msg, _T("MyPaint"), MB_OK | MB_ICONERROR);
        return false;
    }
    m_filePath = path;
    m_canvas.SetModified(false); // CN_STATE 알림으로 제목도 갱신됨
    return true;
}

bool CMyPaintDlg::SaveAsWithDialog()
{
    CString initialName = DisplayName();
    const int dot = initialName.ReverseFind(_T('.'));
    if (dot > 0)
        initialName = initialName.Left(dot);

    CFileDialog dlg(FALSE, _T("png"), initialName,
                    OFN_OVERWRITEPROMPT | OFN_PATHMUSTEXIST | OFN_HIDEREADONLY, kSaveFilter, this);
    dlg.m_ofn.nFilterIndex = m_filePath.IsEmpty() ? 1 : FilterIndexForPath(m_filePath);
    if (dlg.DoModal() != IDOK)
        return false;
    return SaveTo(dlg.GetPathName());
}

void CMyPaintDlg::OnFileNew()
{
    if (!ConfirmDiscardChanges())
        return;
    m_filePath.Empty();
    m_canvas.NewImage(kDefaultWidth, kDefaultHeight);
    UpdateTitle();
}

void CMyPaintDlg::OnFileOpen()
{
    if (!ConfirmDiscardChanges())
        return;

    CFileDialog dlg(TRUE, nullptr, nullptr, OFN_FILEMUSTEXIST | OFN_HIDEREADONLY, kOpenFilter, this);
    if (dlg.DoModal() != IDOK)
        return;

    const CString path = dlg.GetPathName();
    const HRESULT hr = m_canvas.LoadFromFile(path);
    if (FAILED(hr))
    {
        CString msg;
        msg.Format(_T("파일을 열 수 없습니다.\n%s\n\n(오류 코드 0x%08X)"), path.GetString(), static_cast<unsigned>(hr));
        MessageBox(msg, _T("MyPaint"), MB_OK | MB_ICONERROR);
        return;
    }
    m_filePath = path;
    UpdateTitle();
}

void CMyPaintDlg::OnFileSave()
{
    m_canvas.FinishPendingWork();
    if (m_filePath.IsEmpty())
        SaveAsWithDialog();
    else
        SaveTo(m_filePath);
}

void CMyPaintDlg::OnFileSaveAs()
{
    m_canvas.FinishPendingWork();
    SaveAsWithDialog();
}

void CMyPaintDlg::OnFileExit()
{
    PostMessage(WM_CLOSE);
}

