void CMyPaintDlg::OnToolClicked(UINT nID)
{
    static_assert(IDC_TOOL_ELLIPSE - IDC_TOOL_PENCIL == static_cast<int>(ToolType::Ellipse),
                  "도구 버튼 ID 순서와 ToolType 순서가 같아야 합니다.");
    m_canvas.SetTool(static_cast<ToolType>(nID - IDC_TOOL_PENCIL));
    SyncToolUi();
    m_canvas.SetFocus();
}

void CMyPaintDlg::OnSizeComboChanged()
{
    const int sel = m_sizeCombo.GetCurSel();
    if (sel != CB_ERR)
        m_canvas.SetSizeLevel(sel);
}

void CMyPaintDlg::OnTextFont()
{
    LOGFONT lf;
    int pointSize = 0;
    m_canvas.GetTextFont(lf, pointSize);

    // 글꼴 대화 상자는 화면 DPI 기준 높이를 받으므로 포인트 크기를 변환해서 넘깁니다.
    CClientDC dc(this);
    lf.lfHeight = -MulDiv(pointSize, dc.GetDeviceCaps(LOGPIXELSY), 72);

    CFontDialog dlg(&lf, CF_SCREENFONTS | CF_EFFECTS | CF_INITTOLOGFONTSTRUCT, nullptr, this);
    dlg.m_cf.rgbColors = m_colorPanel.GetColor1();
    if (dlg.DoModal() == IDOK)
    {
        LOGFONT chosen;
        dlg.GetCurrentFont(&chosen);
        m_canvas.SetTextFont(chosen, std::max(1, dlg.GetSize() / 10));

        // 글꼴 대화 상자에서 고른 색은 색 1로
        m_colorPanel.SetColor1(dlg.GetColor());
        m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
        UpdateHint();
    }
    m_canvas.FocusTextEdit();
}

void CMyPaintDlg::OnTextTransparent()
{
    m_canvas.SetTextTransparent(IsDlgButtonChecked(IDC_TEXT_TRANSPARENT) == BST_CHECKED);
    m_canvas.FocusTextEdit();
