        _T("삼각형"), _T("직각 삼각형"), _T("마름모"), _T("오각형"), _T("육각형"),
        _T("오른쪽 화살표"), _T("왼쪽 화살표"), _T("위쪽 화살표"), _T("아래쪽 화살표"),
        _T("4각 별"), _T("5각 별"), _T("6각 별"),
