PixelBuffer ApplyFlipRotate(const PixelBuffer& src, FlipRotate op)
{
    const int w = src.width, h = src.height;
    const bool swap = (op == FlipRotate::RotateRight || op == FlipRotate::RotateLeft);
    PixelBuffer dst(swap ? h : w, swap ? w : h);
    for (int y = 0; y < h; ++y)
    {
        for (int x = 0; x < w; ++x)
        {
