            case FlipRotate::RotateLeft:     nx = y; ny = w - 1 - x; break;
            case FlipRotate::Rotate180:      nx = w - 1 - x; ny = h - 1 - y; break;
            case FlipRotate::FlipVertical:   ny = h - 1 - y; break;
            case FlipRotate::FlipHorizontal: nx = w - 1 - x; break;
