    case FlipRotate::RotateLeft:     x = oy; y = width - ox; break;
    case FlipRotate::Rotate180:      x = width - ox; y = height - oy; break;
    case FlipRotate::FlipVertical:   y = height - oy; break;
    case FlipRotate::FlipHorizontal: x = width - ox; break;
    }
