{
    if (newWidth <= 0 || newHeight <= 0 || src.width <= 0 || src.height <= 0)
        return PixelBuffer();
    if (newWidth == src.width && newHeight == src.height)
        return src;

    // 가로 먼저, 그다음 세로 (분리 가능한 필터)
    PixelBuffer temp(newWidth, src.height);
