            [&](int i, uint32_t p) { temp.At(i, y) = p; });
    }
    PixelBuffer dst(newWidth, newHeight);
    for (int x = 0; x < newWidth; ++x)
    {
        ResampleLine(src.height, newHeight,
            [&](int i) { return temp.At(x, i); },
            [&](int i, uint32_t p) { dst.At(x, i) = p; });
    }
    return dst;
}

