/**
 * @file CanvasSelection.cpp
 * @brief 캔버스 선택 영역: 사각형 선택, 이동/복사, 클립보드
 *
 * 선택 영역에는 두 가지 상태가 있습니다.
 * - 고정: 이미지 위에 테두리만 있는 상태 (m_floating == false)
 * - 떠 있음: 선택한 그림을 떼어 m_floatImage로 들고 있는 상태. 이동하거나 붙여넣으면 이 상태가 됩니다.
 *   다른 곳을 클릭하거나 도구를 바꾸면 그 자리에 찍히며(확정) 선택이 끝납니다.
 *
 * 실행 취소 기록은 떼어 낼 때(또는 붙여넣을 때) 한 번만 남기므로,
 * 이동하고 확정한 뒤 실행 취소하면 이동 전 상태로 한 번에 돌아갑니다.
 */
#include "pch.h"
#include "CanvasWnd.h"
#include "CanvasInternal.h"

#ifdef _DEBUG
#define new DEBUG_NEW
#endif

using namespace canvas;

namespace
{
    /**
     * @brief 클립보드 열기. 클립보드 기록(Win+V) 같은 다른 프로그램이 잠깐 열고 있으면
     *        바로 실패하므로 몇 번 다시 시도합니다.
     */
    bool OpenClipboardWithRetry(HWND owner)
    {
        for (int attempt = 0; attempt < 20; ++attempt)
        {
            if (::OpenClipboard(owner))
                return true;
            ::Sleep(10);
        }
        return false;
    }
}

CRect CCanvasWnd::SelectionFromDrag(CPoint a, CPoint b) const
{
    CRect rc(a, b);
    rc.NormalizeRect();
    rc.right += 1; // 끝 픽셀까지 포함
    rc.bottom += 1;
    rc.IntersectRect(rc, ImageBounds());
    return rc;
}

void CCanvasWnd::LiftSelection(bool copy)
{
    if (m_floating || !m_hasSelection)
        return;

    if (!CreateDib32(m_floatImage, m_selRect.Width(), m_selRect.Height(), RGB(255, 255, 255)))
        return;
    m_history.Push(CaptureSnapshot());

    HDC hdc = m_floatImage.GetDC();
    m_image.BitBlt(hdc, 0, 0, m_selRect.Width(), m_selRect.Height(), m_selRect.left, m_selRect.top);
    m_floatImage.ReleaseDC();

    if (!copy)
    {
        // 옮기면 원래 자리는 배경색(색 2)으로 비움
        hdc = m_image.GetDC();
        CDC::FromHandle(hdc)->FillSolidRect(m_selRect, m_color2);
        m_image.ReleaseDC();
    }
    m_floating = true;
    MarkModified();
}

void CCanvasWnd::StampFloating()
{
    if (!m_floating || m_floatImage.IsNull())
        return;
    HDC hdc = m_image.GetDC();
    m_floatImage.BitBlt(hdc, m_selRect.left, m_selRect.top); // 이미지 밖으로 나간 부분은 잘림
    m_image.ReleaseDC();
}

void CCanvasWnd::BeginMoveSelection(CPoint imgPt, bool copy)
{
    if (m_floating && copy)
        StampFloating(); // 떠 있는 그림을 Ctrl+드래그: 지금 자리에 하나 찍고 사본을 옮김
    else
        LiftSelection(copy);

    m_moveGrab = imgPt - m_selRect.TopLeft();
    BeginDrag(DragMode::MoveSelection, DragButton::Left, imgPt);
    Invalidate(FALSE);
}

void CCanvasWnd::DropSelection()
{
    if (m_floating)
    {
        StampFloating();
        m_floatImage.Destroy();
        m_floating = false;
    }
    if (m_hasSelection)
    {
        m_hasSelection = false;
        Invalidate(FALSE);
        NotifySelectionSize();
        NotifyParent(CN_STATE);
    }
}

void CCanvasWnd::MoveSelectionBy(int dx, int dy)
{
    if (!m_hasSelection || m_dragMode != DragMode::None)
        return;
    LiftSelection(false);
    m_selRect.OffsetRect(dx, dy);
    Invalidate(FALSE);
}

void CCanvasWnd::SelectAll()
{
    ChangeToolInternal(ToolType::Select); // 진행 중인 작업도 확정됨
    m_selRect = ImageBounds();
    m_hasSelection = !m_selRect.IsRectEmpty();
    Invalidate(FALSE);
    NotifySelectionSize();
    NotifyParent(CN_STATE);
}

void CCanvasWnd::DeleteSelection()
{
    if (!m_hasSelection)
        return;

    if (m_floating)
    {
        // 떼어 낸 그림만 버리면 됨 (원래 자리는 떼어 낼 때 이미 비웠음)
        m_floatImage.Destroy();
        m_floating = false;
    }
    else
    {
        m_history.Push(CaptureSnapshot());
        HDC hdc = m_image.GetDC();
        CDC::FromHandle(hdc)->FillSolidRect(m_selRect, m_color2);
        m_image.ReleaseDC();
    }
    m_hasSelection = false;
    Invalidate(FALSE);
    NotifySelectionSize();
    MarkModified();
}

bool CCanvasWnd::CopySelection()
{
    if (!m_hasSelection)
        return false;
    if (m_floating)
        return WriteClipboard(m_floatImage, CRect(0, 0, m_floatImage.GetWidth(), m_floatImage.GetHeight()));
    return WriteClipboard(m_image, m_selRect);
}

bool CCanvasWnd::CutSelection()
{
    if (!CopySelection())
        return false;
    DeleteSelection();
    return true;
}

bool CCanvasWnd::CanPaste()
{
    return ::IsClipboardFormatAvailable(CF_DIB) || ::IsClipboardFormatAvailable(CF_BITMAP);
}

bool CCanvasWnd::Paste()
{
    CImage clip;
    if (!ReadClipboard(clip))
        return false;

    ChangeToolInternal(ToolType::Select); // 진행 중인 작업 확정 후 선택 도구로

    ImageSnapshot before = CaptureSnapshot();
    const CSize size = GetImageSize();
    if (clip.GetWidth() > size.cx || clip.GetHeight() > size.cy)
