            ::AbortDoc(hdc);
            error = _T("이미지를 프린터로 보내지 못했습니다.");
            return false;
        }
        if (::EndDoc(hdc) <= 0)
        {
            error = _T("인쇄 작업을 마치지 못했습니다.");
            return false;
        }
        return true;
    }
}

