#pragma once

/**
 * @file ShapeCombo.h
 * @brief 도형 아이콘과 이름을 함께 보여 주는 콤보 상자
 */

#include "Shapes.h"

/**
 * @brief 도형 선택 콤보 상자 (CBS_OWNERDRAWFIXED | CBS_HASSTRINGS)
 *
 * 항목마다 도형 아이콘을 직접 그립니다. 리소스의 콤보 상자를 DDX_Control로 연결한 뒤 Init을 부르세요.
 */
class CShapeCombo : public CComboBox
{
public:
    /** @brief 도형 23종을 채우고 항목 높이를 맞춥니다. */
    void Init();
    /** @brief 선택된 도형 */
    ShapeKind GetSelectedKind() const;
    /** @brief 도형 선택 */
    void SelectKind(ShapeKind kind);

protected:
    void DrawItem(LPDRAWITEMSTRUCT lpDrawItemStruct) override;
    void MeasureItem(LPMEASUREITEMSTRUCT lpMeasureItemStruct) override;

private:
    int ItemHeight() const;
};

/**
 * @file ShapeCombo.cpp
 * @brief 도형 선택 콤보 상자 구현
 */
#include "pch.h"
#include "ShapeCombo.h"

#ifdef _DEBUG
#define new DEBUG_NEW
#endif

int CShapeCombo::ItemHeight() const
{
    const int dpi = GetSafeHwnd() ? static_cast<int>(GetDpiForWindow(m_hWnd)) : 96;
    return MulDiv(20, dpi, 96);
}

void CShapeCombo::Init()
{
    ResetContent();
    for (int i = 0; i < kShapeKindCount; ++i)
    {
        const int index = AddString(ShapeName(static_cast<ShapeKind>(i)));
        SetItemData(index, static_cast<DWORD_PTR>(i));
    }
    // 대화 상자가 만들어질 때 받은 WM_MEASUREITEM은 연결 전이라 기본 높이이므로 다시 지정
    SetItemHeight(-1, ItemHeight()); // 선택 표시 부분
    SetItemHeight(0, ItemHeight());  // 목록 항목
    SetCurSel(0);
}

ShapeKind CShapeCombo::GetSelectedKind() const
{
    const int sel = GetCurSel();
    if (sel == CB_ERR)
        return ShapeKind::Line;
    return static_cast<ShapeKind>(GetItemData(sel));
}

void CShapeCombo::SelectKind(ShapeKind kind)
{
    for (int i = 0; i < GetCount(); ++i)
    {
        if (static_cast<ShapeKind>(GetItemData(i)) == kind)
        {
            SetCurSel(i);
            return;
        }
    }
}

void CShapeCombo::MeasureItem(LPMEASUREITEMSTRUCT lpMeasureItemStruct)
{
    lpMeasureItemStruct->itemHeight = ItemHeight();
}

void CShapeCombo::DrawItem(LPDRAWITEMSTRUCT dis)
{
    if (dis->itemID == static_cast<UINT>(-1))
        return;

    CDC* pDC = CDC::FromHandle(dis->hDC);
    const CRect rc = dis->rcItem;
    const bool selected = (dis->itemState & ODS_SELECTED) != 0;
    const bool disabled = (dis->itemState & ODS_DISABLED) != 0;

    const COLORREF back = GetSysColor(selected ? COLOR_HIGHLIGHT : COLOR_WINDOW);
    const COLORREF fore = GetSysColor(disabled ? COLOR_GRAYTEXT : (selected ? COLOR_HIGHLIGHTTEXT : COLOR_WINDOWTEXT));
    pDC->FillSolidRect(rc, back);

    // 왼쪽: 도형 아이콘
    const int pad = std::max(3, rc.Height() / 6);
    const int iconSize = rc.Height() - pad * 2;
    const CRect icon(rc.left + pad, rc.top + pad, rc.left + pad + iconSize, rc.top + pad + iconSize);
    DrawShapeIcon(*pDC, static_cast<ShapeKind>(dis->itemData), icon, fore);

    // 오른쪽: 이름
    CString text;
    GetLBText(dis->itemID, text);
    CRect textRect = rc;
    textRect.left = icon.right + pad * 2;
    pDC->SetBkMode(TRANSPARENT);
    pDC->SetTextColor(fore);
    pDC->DrawText(text, textRect, DT_SINGLELINE | DT_VCENTER | DT_END_ELLIPSIS | DT_NOPREFIX);

    if ((dis->itemState & ODS_FOCUS) && !(dis->itemState & ODS_NOFOCUSRECT))
        pDC->DrawFocusRect(rc);
}

#pragma once

/**
 * @file ResizeSkewDlg.h
 * @brief "크기 조정 및 기울이기" 대화 상자
 */

/**
 * @brief 크기 조정(백분율/픽셀, 가로세로 비율 유지)과 기울이기(도) 값을 입력받습니다.
 */
class CResizeSkewDlg : public CDialog
{
public:
    /**
     * @param original 변환 대상의 현재 크기 (선택 영역 또는 이미지)
     * @param pParent 부모 창
     */
    CResizeSkewDlg(CSize original, CWnd* pParent = nullptr);

    CSize m_newSize;   ///< [결과] 새 크기 (픽셀)
    int m_skewX = 0;   ///< [결과] 가로 기울기 (도)
    int m_skewY = 0;   ///< [결과] 세로 기울기 (도)

protected:
    BOOL OnInitDialog() override;
    void OnOK() override;

    afx_msg void OnUnitChanged();
    afx_msg void OnWidthChanged();
    afx_msg void OnHeightChanged();
    DECLARE_MESSAGE_MAP()

private:
    bool IsPercent() const;
    /** @brief 한쪽 값이 바뀌었을 때 비율 유지가 켜져 있으면 다른 쪽을 맞춤 */
    void SyncAspect(bool widthChanged);

    CSize m_original;
    bool m_percentMode = true;  ///< 지금 입력란에 보이는 값의 단위
    bool m_updating = false;    ///< 값을 코드에서 바꾸는 중 (EN_CHANGE 재귀 방지)
};

/**
 * @file ResizeSkewDlg.cpp
 * @brief "크기 조정 및 기울이기" 대화 상자 구현
 */
#include "pch.h"
#include "MyPaint.h"
#include "ResizeSkewDlg.h"

#include <cmath>

#ifdef _DEBUG
#define new DEBUG_NEW
#endif

namespace
{
    constexpr int kMaxPercent = 1000;
    constexpr int kMaxPixels = 16000;
    constexpr int kMaxSkew = 89;
}

BEGIN_MESSAGE_MAP(CResizeSkewDlg, CDialog)
    ON_BN_CLICKED(IDC_RS_PERCENT, &CResizeSkewDlg::OnUnitChanged)
    ON_BN_CLICKED(IDC_RS_PIXELS, &CResizeSkewDlg::OnUnitChanged)
    ON_EN_CHANGE(IDC_RS_WIDTH, &CResizeSkewDlg::OnWidthChanged)
    ON_EN_CHANGE(IDC_RS_HEIGHT, &CResizeSkewDlg::OnHeightChanged)
END_MESSAGE_MAP()

CResizeSkewDlg::CResizeSkewDlg(CSize original, CWnd* pParent)
    : CDialog(IDD_RESIZE_SKEW, pParent), m_newSize(original), m_original(original)
{
}

BOOL CResizeSkewDlg::OnInitDialog()
{
    CDialog::OnInitDialog();

    CString info;
    info.Format(_T("현재 크기: %d × %dpx"), m_original.cx, m_original.cy);
    SetDlgItemText(IDC_RS_INFO, info);

    m_updating = true;
    CheckRadioButton(IDC_RS_PERCENT, IDC_RS_PIXELS, IDC_RS_PERCENT);
    m_percentMode = true;
    SetDlgItemInt(IDC_RS_WIDTH, 100);
    SetDlgItemInt(IDC_RS_HEIGHT, 100);
    CheckDlgButton(IDC_RS_KEEP_ASPECT, BST_CHECKED);
    SetDlgItemInt(IDC_RS_SKEW_X, 0, TRUE);
    SetDlgItemInt(IDC_RS_SKEW_Y, 0, TRUE);
    m_updating = false;

    GotoDlgCtrl(GetDlgItem(IDC_RS_WIDTH));
    return FALSE;
}

bool CResizeSkewDlg::IsPercent() const
{
    return IsDlgButtonChecked(IDC_RS_PERCENT) == BST_CHECKED;
}

void CResizeSkewDlg::OnUnitChanged()
{
    const bool toPercent = IsPercent();
    if (toPercent == m_percentMode)
        return;

    // 지금 보이는 값을 새 단위로 바꿔서 다시 표시
    BOOL okW = FALSE, okH = FALSE;
    const int w = static_cast<int>(GetDlgItemInt(IDC_RS_WIDTH, &okW));
    const int h = static_cast<int>(GetDlgItemInt(IDC_RS_HEIGHT, &okH));
    m_updating = true;
    if (toPercent)
    {
        if (okW) SetDlgItemInt(IDC_RS_WIDTH, static_cast<UINT>(std::lround(w * 100.0 / m_original.cx)));
        if (okH) SetDlgItemInt(IDC_RS_HEIGHT, static_cast<UINT>(std::lround(h * 100.0 / m_original.cy)));
    }
    else
    {
        if (okW) SetDlgItemInt(IDC_RS_WIDTH, static_cast<UINT>(std::lround(w * m_original.cx / 100.0)));
        if (okH) SetDlgItemInt(IDC_RS_HEIGHT, static_cast<UINT>(std::lround(h * m_original.cy / 100.0)));
    }
    m_updating = false;
    m_percentMode = toPercent;
}

void CResizeSkewDlg::SyncAspect(bool widthChanged)
{
    if (m_updating || IsDlgButtonChecked(IDC_RS_KEEP_ASPECT) != BST_CHECKED)
        return;

    BOOL ok = FALSE;
    const int value = static_cast<int>(GetDlgItemInt(widthChanged ? IDC_RS_WIDTH : IDC_RS_HEIGHT, &ok));
    if (!ok)
        return;

    int other = value; // 백분율이면 같은 값
    if (!m_percentMode)
    {
        other = widthChanged ? static_cast<int>(std::lround(value * static_cast<double>(m_original.cy) / m_original.cx))
                             : static_cast<int>(std::lround(value * static_cast<double>(m_original.cx) / m_original.cy));
    }
    m_updating = true;
    SetDlgItemInt(widthChanged ? IDC_RS_HEIGHT : IDC_RS_WIDTH, static_cast<UINT>(std::max(other, 1)));
    m_updating = false;
}

void CResizeSkewDlg::OnWidthChanged()
{
    SyncAspect(true);
}

void CResizeSkewDlg::OnHeightChanged()
{
    SyncAspect(false);
}

void CResizeSkewDlg::OnOK()
{
    BOOL okW = FALSE, okH = FALSE, okSx = FALSE, okSy = FALSE;
    const int w = static_cast<int>(GetDlgItemInt(IDC_RS_WIDTH, &okW));
    const int h = static_cast<int>(GetDlgItemInt(IDC_RS_HEIGHT, &okH));
    const int sx = static_cast<int>(GetDlgItemInt(IDC_RS_SKEW_X, &okSx, TRUE));
    const int sy = static_cast<int>(GetDlgItemInt(IDC_RS_SKEW_Y, &okSy, TRUE));

    const int maxSize = m_percentMode ? kMaxPercent : kMaxPixels;
    if (!okW || !okH || w < 1 || h < 1 || w > maxSize || h > maxSize)
    {
        CString msg;
        msg.Format(_T("크기는 1부터 %d까지 입력하세요."), maxSize);
        MessageBox(msg, _T("크기 조정 및 기울이기"), MB_OK | MB_ICONWARNING);
        GotoDlgCtrl(GetDlgItem(okW && w >= 1 && w <= maxSize ? IDC_RS_HEIGHT : IDC_RS_WIDTH));
        return;
    }
    if (!okSx || !okSy || std::abs(sx) > kMaxSkew || std::abs(sy) > kMaxSkew)
    {
        CString msg;
        msg.Format(_T("기울기는 -%d부터 %d까지(도) 입력하세요."), kMaxSkew, kMaxSkew);
        MessageBox(msg, _T("크기 조정 및 기울이기"), MB_OK | MB_ICONWARNING);
        GotoDlgCtrl(GetDlgItem(okSx && std::abs(sx) <= kMaxSkew ? IDC_RS_SKEW_Y : IDC_RS_SKEW_X));
        return;
    }

    if (m_percentMode)
    {
        m_newSize.cx = std::max(1, static_cast<int>(std::lround(m_original.cx * w / 100.0)));
        m_newSize.cy = std::max(1, static_cast<int>(std::lround(m_original.cy * h / 100.0)));
    }
    else
    {
        m_newSize = CSize(w, h);
    }
    m_skewX = sx;
    m_skewY = sy;
    CDialog::OnOK();
}

#pragma once

/**
 * @file Printing.h
 * @brief 페이지 설정과 이미지 인쇄
 */

/**
 * @brief 인쇄 설정. 프린터 선택과 용지·방향(DEVMODE), 여백을 다음 인쇄까지 기억합니다.
 */
class CPrintSettings
{
public:
    CPrintSettings() = default;
    ~CPrintSettings();
    CPrintSettings(const CPrintSettings&) = delete;
    CPrintSettings& operator=(const CPrintSettings&) = delete;

    HGLOBAL m_hDevMode = nullptr;   ///< 프린터 설정 (공용 대화 상자가 할당, 이 개체가 해제)
    HGLOBAL m_hDevNames = nullptr;  ///< 프린터 이름
    CRect m_margins{ 1000, 1000, 1000, 1000 }; ///< 여백 (1/100 mm, 기본 10mm)
};

/**
 * @brief 페이지 설정 대화 상자 (용지, 방향, 여백, 프린터)
 * @return 확인을 눌렀으면 true
 */
bool ShowPageSetup(CWnd* pParent, CPrintSettings& settings);

/**
 * @brief 인쇄 대화 상자를 띄우고 이미지를 한 페이지에 인쇄합니다.
 *
 * 화면과 같은 크기(96 DPI 기준)로 여백 안쪽 왼쪽 위에 인쇄하고,
 * 여백 안에 들어가지 않으면 비율을 유지한 채 줄입니다.
 *
 * @param error [out] 실패했을 때의 설명 (취소하면 비어 있음)
 * @return 인쇄했으면 true
 */
bool PrintImage(CWnd* pParent, CImage& image, LPCTSTR docName, CPrintSettings& settings, CString& error);

/**
 * @file Printing.cpp
 * @brief 페이지 설정과 이미지 인쇄 구현
 */
#include "pch.h"
#include "Printing.h"

#include <cmath>

#ifdef _DEBUG
#define new DEBUG_NEW
#endif

namespace
{
    /**
     * @brief 프린터 DC에 이미지 한 페이지를 인쇄
     */
    bool RenderPage(HDC hdc, CImage& image, const CRect& margins, LPCTSTR docName, CString& error)
    {
        DOCINFO di{ sizeof(DOCINFO) };
        di.lpszDocName = docName;
        if (::StartDoc(hdc, &di) <= 0)
        {
            error = _T("인쇄 작업을 시작하지 못했습니다.");
            return false;
        }
        if (::StartPage(hdc) <= 0)
        {
            ::AbortDoc(hdc);
            error = _T("페이지를 시작하지 못했습니다.");
            return false;
        }

        // 장치 정보: 인쇄 가능 영역(HORZRES/VERTRES)은 용지 가장자리에서 PHYSICALOFFSET만큼 안쪽에서 시작
        const int dpiX = ::GetDeviceCaps(hdc, LOGPIXELSX);
        const int dpiY = ::GetDeviceCaps(hdc, LOGPIXELSY);
        const int printableW = ::GetDeviceCaps(hdc, HORZRES);
        const int printableH = ::GetDeviceCaps(hdc, VERTRES);
        const int paperW = ::GetDeviceCaps(hdc, PHYSICALWIDTH);
        const int paperH = ::GetDeviceCaps(hdc, PHYSICALHEIGHT);
        const int offsetX = ::GetDeviceCaps(hdc, PHYSICALOFFSETX);
        const int offsetY = ::GetDeviceCaps(hdc, PHYSICALOFFSETY);

        // 여백(1/100 mm)을 장치 픽셀로 바꾸고, 인쇄 가능 영역 좌표로 옮김
        CRect area(MulDiv(margins.left, dpiX, 2540) - offsetX,
                   MulDiv(margins.top, dpiY, 2540) - offsetY,
                   paperW - MulDiv(margins.right, dpiX, 2540) - offsetX,
                   paperH - MulDiv(margins.bottom, dpiY, 2540) - offsetY);
        area.IntersectRect(area, CRect(0, 0, printableW, printableH));
        if (area.IsRectEmpty())
            area = CRect(0, 0, printableW, printableH); // 여백이 너무 크면 인쇄 가능 영역 전체

        // 화면과 같은 크기 = 이미지 픽셀을 96 DPI로 보고 프린터 해상도로 환산. 넘치면 줄임
        const int w = image.GetWidth();
        const int h = image.GetHeight();
        const double naturalW = w * dpiX / 96.0;
        const double naturalH = h * dpiY / 96.0;
        const double scale = std::min({ 1.0, area.Width() / naturalW, area.Height() / naturalH });
        const int destW = std::max(1, static_cast<int>(std::lround(naturalW * scale)));
        const int destH = std::max(1, static_cast<int>(std::lround(naturalH * scale)));

        // 32비트 위→아래 DIB를 그대로 넘김 (높이 음수 = 위→아래)
        BITMAPINFO bmi{};
        bmi.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
        bmi.bmiHeader.biWidth = w;
        bmi.bmiHeader.biHeight = -h;
        bmi.bmiHeader.biPlanes = 1;
        bmi.bmiHeader.biBitCount = 32;
        bmi.bmiHeader.biCompression = BI_RGB;

        GdiFlush();
        ::SetStretchBltMode(hdc, HALFTONE);
        ::SetBrushOrgEx(hdc, 0, 0, nullptr);
        const int lines = ::StretchDIBits(hdc, area.left, area.top, destW, destH, 0, 0, w, h,
                                          image.GetPixelAddress(0, 0), &bmi, DIB_RGB_COLORS, SRCCOPY);

        const bool pageOk = ::EndPage(hdc) > 0;
        if (lines == 0 || lines == GDI_ERROR || !pageOk)
        {
            ::AbortDoc(hdc);
            error = _T("이미지를 프린터로 보내지 못했습니다.");
            return false;
        }
        if (::EndDoc(hdc) <= 0)
        {
            error = _T("인쇄 작업을 마치지 못했습니다.");
            return false;
        }
        return true;
    }
}

CPrintSettings::~CPrintSettings()
{
    if (m_hDevMode)
        ::GlobalFree(m_hDevMode);
    if (m_hDevNames)
        ::GlobalFree(m_hDevNames);
}

bool ShowPageSetup(CWnd* pParent, CPrintSettings& settings)
{
    CPageSetupDialog dlg(PSD_MARGINS | PSD_INHUNDREDTHSOFMILLIMETERS, pParent);
    dlg.m_psd.hDevMode = settings.m_hDevMode;
    dlg.m_psd.hDevNames = settings.m_hDevNames;
    dlg.m_psd.rtMargin = settings.m_margins;

    const INT_PTR result = dlg.DoModal();

    // 대화 상자가 핸들을 다시 할당했을 수 있으므로 돌려받고, 대화 상자가 해제하지 않도록 비움
    settings.m_hDevMode = dlg.m_psd.hDevMode;
    settings.m_hDevNames = dlg.m_psd.hDevNames;
    dlg.m_psd.hDevMode = nullptr;
    dlg.m_psd.hDevNames = nullptr;

    if (result != IDOK)
        return false;
    settings.m_margins = dlg.m_psd.rtMargin;
    return true;
}

bool PrintImage(CWnd* pParent, CImage& image, LPCTSTR docName, CPrintSettings& settings, CString& error)
{
    error.Empty();
    if (image.IsNull())
        return false;

    CPrintDialog dlg(FALSE, PD_ALLPAGES | PD_USEDEVMODECOPIESANDCOLLATE | PD_NOPAGENUMS | PD_NOSELECTION
                          | PD_HIDEPRINTTOFILE | PD_RETURNDC, pParent);
    dlg.m_pd.hDevMode = settings.m_hDevMode;
    dlg.m_pd.hDevNames = settings.m_hDevNames;

    const INT_PTR result = dlg.DoModal();

    settings.m_hDevMode = dlg.m_pd.hDevMode;
    settings.m_hDevNames = dlg.m_pd.hDevNames;
    dlg.m_pd.hDevMode = nullptr;
    dlg.m_pd.hDevNames = nullptr;
    HDC hdc = dlg.m_pd.hDC;
    dlg.m_pd.hDC = nullptr;

    if (result != IDOK)
    {
        if (hdc)
            ::DeleteDC(hdc);
        return false;
    }
    if (!hdc)
    {
        error = _T("프린터를 열지 못했습니다.");
        return false;
    }

    const bool ok = RenderPage(hdc, image, settings.m_margins, docName, error);
    ::DeleteDC(hdc);
    return ok;
}

