    uint8_t& cov = CoverageAt(x, y);
    if (alpha <= cov)
        return; // 이번 획에서 이미 더 진하게 칠한 곳
    cov = static_cast<uint8_t>(alpha);
    // 획을 긋기 전 픽셀을 바탕으로 섞으므로 한 획 안에서는 쌓이지 않음
    const uint32_t base = m_before[static_cast<size_t>(y) * m_w + x];
