    case BrushKind::Airbrush:   return std::max(2.0, m_width * 0.75);
    case BrushKind::Crayon:     return std::max(1.0, m_width / 3.0);
    case BrushKind::Watercolor: return std::max(1.0, m_width / 5.0);
