}

void CBrushStroke::StampCoverage(CPoint p, CRect& dirty)
{
    int r = 0;
    switch (m_kind)
    {
    case BrushKind::Crayon:
    {
        // 크레용: 둥근 자국 중 종이 결(위치 잡음)이 낮은 곳만 칠함 → 군데군데 빔
        r = std::max(1, m_width / 2);
        for (int y = -r; y <= r; ++y)
            for (int x = -r; x <= r; ++x)
                if (x * x + y * y <= r * r && GrainAt(p.x + x, p.y + y) < 160)
