                    continue;
                const double grain = 0.8 + 0.2 * GrainAt(p.x + x, p.y + y) / 255.0;
                Cover(p.x + x, p.y + y, static_cast<int>(110 * (1.0 - d2 * 0.7) * grain));
            }
