/** @brief 브러시 종류 (목록에 보이는 순서) */
enum class BrushKind
{
    Normal,        ///< 브러시: 둥근 붓
    Calligraphy1,  ///< 캘리그래피 1: "/" 방향 납작한 펜촉
    Calligraphy2,  ///< 캘리그래피 2: "\" 방향 납작한 펜촉
