import sys, os
d = sys.argv[1]

def patch(name, pairs):
    p = os.path.join(d, name)
    s = open(p, encoding='utf-8').read()
    for old, new, count in pairs:
        n = s.count(old)
        assert n >= 1, (name, old[:70])
        if count:
            assert n == count, (name, old[:70], n)
        s = s.replace(old, new)
    open(p, 'w', encoding='utf-8').write(s)

# ---------------- CanvasSelection.cpp ----------------
patch('CanvasSelection.cpp', [
    ('    ReplaceImage(m_floatImage, image);\n    m_floating = true;\n    MarkModified();\n}',
     '    ReplaceImage(m_floatSource, image);\n    RebuildFloatImage();\n    m_floating = true;\n    MarkModified();\n}', 1),
    ('    ReplaceImage(m_floatImage, clip);\n',
     '    ReplaceImage(m_floatSource, clip);\n    RebuildFloatImage();\n', 1),
    ('        m_floatImage.Destroy();\n        m_floating = false;\n',
     '        m_floatImage.Destroy();\n        m_floatSource.Destroy();\n        m_floating = false;\n', 2),
    ('''void CCanvasWnd::BeginMoveSelection(CPoint imgPt, bool copy)''',
     '''void CCanvasWnd::RebuildFloatImage()
{
    // 화면 표시·찍기용 그림 = 원본. 투명 선택이면 색 2와 같은 불투명 픽셀을 투명(0)으로
    if (m_floatSource.IsNull())
        return;
    const int w = m_floatSource.GetWidth();
    const int h = m_floatSource.GetHeight();
    if (!CreateDib32(m_floatImage, w, h, RGB(0, 0, 0)))
        return;
    GdiFlush();
    const uint32_t key = ToPixel(m_color2);
    for (int y = 0; y < h; ++y)
    {
        const auto* src = static_cast<const uint32_t*>(m_floatSource.GetPixelAddress(0, y));
        auto* dst = static_cast<uint32_t*>(m_floatImage.GetPixelAddress(0, y));
        for (int x = 0; x < w; ++x)
        {
            const uint32_t p = src[x];
            dst[x] = (m_transparentSelection && (p >> 24) == 255 && (p & 0x00FFFFFF) == key) ? 0 : p;
        }
    }
}

void CCanvasWnd::SetTransparentSelection(bool transparent)
{
    m_transparentSelection = transparent;
    if (m_floating)
    {
        RebuildFloatImage();
        Invalidate(FALSE);
    }
}

void CCanvasWnd::BeginMoveSelection(CPoint imgPt, bool copy)''', 1),
])

