    ('const PixelBuffer result = ApplyFlipRotate(ToBuffer(m_floatImage), op);\n        if (!FromBuffer(m_floatImage, result))\n            return;\n',
     'const PixelBuffer result = ApplyFlipRotate(ToBuffer(m_floatSource), op);\n        if (!FromBuffer(m_floatSource, result))\n            return;\n        RebuildFloatImage();\n', 1),
    ('PixelBuffer buffer = Resize(ToBuffer(m_floatImage), newSize.cx, newSize.cy);',
     'PixelBuffer buffer = Resize(ToBuffer(m_floatSource), newSize.cx, newSize.cy);', 1),
    ('        if (!FromBuffer(m_floatImage, buffer))\n            return false;\n',
     '        if (!FromBuffer(m_floatSource, buffer))\n            return false;\n        RebuildFloatImage();\n', 1),
    ('    m_floatImage.Destroy();\n    m_floating = false;\n    ClearSelectionState();',
     '    m_floatImage.Destroy();\n    m_floatSource.Destroy();\n    m_floating = false;\n    ClearSelectionState();', 1),
    ('''void CCanvasWnd::CropToSelection()''',
     '''void CCanvasWnd::SetCanvasSize(CSize size)
{
    FinishPendingWork();
    size.cx = std::clamp<int>(size.cx, 1, kMaxImageSide);
    size.cy = std::clamp<int>(size.cy, 1, kMaxImageSide);
    ResizeCanvasTo(size, true);
}

void CCanvasWnd::CropToSelection()''', 1),
])

