{
    static const LPCTSTR kNames[kShapePaintCount] = {
        _T("없음"), _T("단색"), _T("크레용"), _T("마커"), _T("유화"), _T("자연스러운 연필"), _T("수채화"),
    };
    const int i = static_cast<int>(paint);
