    ('''    /** @brief 에어브러시처럼 누르고 있는 동안 계속 칠하는 브러시인지 */''', '''    /**
     * @brief 영역을 이 브러시의 질감으로 채움 (도형 질감 채우기)
     * @param mask area 크기의 바이트 배열 (0이 아니면 채울 픽셀)
     * @param area mask가 놓인 위치 (이미지 좌표)
     */
    CRect FillArea(const std::vector<uint8_t>& mask, const CRect& area);

    /** @brief 에어브러시처럼 누르고 있는 동안 계속 칠하는 브러시인지 */'''),
