std::vector<CRect> CCanvasWnd::SelectionHandleRects() const
{
    if (!m_hasSelection || (m_tool != ToolType::Select && m_tool != ToolType::FreeSelect))
        return {};
    if (m_dragMode != DragMode::None && m_dragMode != DragMode::SelectionHandle)
        return {};
