int CCanvasWnd::HitTestSelectionHandle(CPoint clientPt) const
{
    const std::vector<CRect> rects = SelectionHandleRects();
    for (size_t i = 0; i < rects.size(); ++i)
    {
        CRect rc = rects[i];
        rc.InflateRect(2, 2);
        if (rc.PtInRect(clientPt))
            return static_cast<int>(i);
    }
    return -1;
