#include "pch.h"
#include "MyPaint.h"
#include "Printing.h"

#include <cmath>

#ifdef _DEBUG
#define new DEBUG_NEW
#endif

// ---------------------------------------------------------------------------
// 설정 / 용지 정보 / 배치 계산
// ---------------------------------------------------------------------------

CPrintSettings::~CPrintSettings()
{
    if (m_hDevMode)
        ::GlobalFree(m_hDevMode);
    if (m_hDevNames)
        ::GlobalFree(m_hDevNames);
