BOOL CMyPaintDlg::OnInitDialog()
{
    CDialog::OnInitDialog();

    SetIcon(m_hIcon, TRUE);  // 큰 아이콘
    SetIcon(m_hIcon, FALSE); // 작은 아이콘

    m_hAccel = ::LoadAccelerators(AfxGetResourceHandle(), MAKEINTRESOURCE(IDR_ACCEL));

    m_colorPanel.SubclassDlgItem(IDC_COLOR_PANEL, this);
    m_statusBar.Create(WS_CHILD | WS_VISIBLE | SBARS_SIZEGRIP, CRect(0, 0, 0, 0), this, IDC_STATUSBAR);
    m_canvas.Create(this, IDC_CANVAS);

    // 도형 옵션: 종류 목록, 윤곽선(없음/단색), 채우기(없음/단색)
    m_shapeCombo.Init();
    for (CComboBox* combo : { &m_outlineCombo, &m_fillCombo })
    {
        combo->AddString(_T("없음"));
        combo->AddString(_T("단색"));
    }
    m_outlineCombo.SetCurSel(1);
    m_fillCombo.SetCurSel(0);
    m_canvas.SetShapeKind(m_shapeCombo.GetSelectedKind());
    m_canvas.SetShapeOptions(true, false);
    UpdateShapeControls();

    // 브러시 종류
    for (int i = 0; i < kBrushKindCount; ++i)
        m_brushCombo.AddString(BrushName(static_cast<BrushKind>(i)));
    m_brushCombo.SetCurSel(0);
    m_canvas.SetBrushKind(BrushKind::Normal);

    m_canvas.SetTool(ToolType::Pencil);
    m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
    SyncToolUi();

    m_canvas.NewImage(kDefaultWidth, kDefaultHeight);

    LayoutControls();
    UpdateTitle();
    UpdateStatusImageSize();
    UpdateStatusZoom();

    m_canvas.SetFocus();
    return FALSE; // 포커스를 직접 지정했음
}
void CMyPaintDlg::LayoutControls()
{
    if (!m_canvas.GetSafeHwnd() || !m_statusBar.GetSafeHwnd())
        return;

    CRect client;
    GetClientRect(&client);

    int canvasBottom = client.bottom;
    if (m_statusVisible)
    {
        // 상태 표시줄은 WM_SIZE를 받으면 스스로 아래쪽에 붙습니다.
        m_statusBar.SendMessage(WM_SIZE);
        CRect rcStatus;
        m_statusBar.GetWindowRect(&rcStatus);
        ScreenToClient(&rcStatus);
        canvasBottom = rcStatus.top;

        const int dpi = static_cast<int>(GetDpiForWindow(m_hWnd));
        int parts[SP_COUNT] = {};
        const int widths[SP_COUNT - 1] = { 110, 110, 110, 70 };
        int x = 0;
        for (int i = 0; i < SP_COUNT - 1; ++i)
        {
            x += MulDiv(widths[i], dpi, 96);
            parts[i] = x;
        }
        parts[SP_HINT] = -1;
        m_statusBar.SetParts(SP_COUNT, parts);
    }

    // 캔버스는 도구 패널 오른쪽부터 상태 표시줄 위까지 채웁니다.
    CRect rcGroup;
    GetDlgItem(IDC_TOOL_GROUP)->GetWindowRect(&rcGroup);
    ScreenToClient(&rcGroup);
    const int left = rcGroup.right + rcGroup.left;
    m_canvas.MoveWindow(left, 0, std::max<int>(0, client.right - left), std::max(0, canvasBottom));
}
void CMyPaintDlg::UpdateShapeControls()
{
    // 직선/곡선은 채울 수 없고 윤곽선을 끌 수도 없음
    const bool open = IsOpenShape(m_shapeCombo.GetSelectedKind());
    m_outlineCombo.EnableWindow(!open);
    m_fillCombo.EnableWindow(!open);
    GetDlgItem(IDC_OUTLINE_LABEL)->EnableWindow(!open);
    GetDlgItem(IDC_FILL_LABEL)->EnableWindow(!open);
}
void CMyPaintDlg::OnShapeOptionsChanged()
{
    m_canvas.SetShapeOptions(m_outlineCombo.GetCurSel() == 1, m_fillCombo.GetCurSel() == 1);
}
