    pDC->SetViewportOrg(-area.left, -area.top);'''),
    ('''    DrawShape(*pDC, m_shape, s);
    maskImage.ReleaseDC();''', '''    DrawShape(*pDC, m_shape, s);
    pDC->RestoreDC(saved);
