#pragma once

/**
 * @file Theme.h
 * @brief 어두운 테마: 색, 글꼴, 아이콘 그리기, 창을 어둡게 만드는 도우미
 *
 * 도구 막대, 상태 표시줄, 드롭다운은 표준 컨트롤 대신 직접 그리는 창이고,
 * 모두 이 파일의 색과 그리기 함수를 함께 써서 한 가지 모양으로 보이게 합니다.
 */

namespace theme
{
