221	void CMyPaintDlg::LayoutControls()
222	{
223	    if (!m_canvas.GetSafeHwnd() || !m_statusBar.GetSafeHwnd())
224	        return;
225	
226	    CRect client;
227	    GetClientRect(&client);
228	
229	    int canvasBottom = client.bottom;
230	    if (m_statusVisible)
231	    {
232	        // 상태 표시줄은 WM_SIZE를 받으면 스스로 아래쪽에 붙습니다.
233	        m_statusBar.SendMessage(WM_SIZE);
234	        CRect rcStatus;
235	        m_statusBar.GetWindowRect(&rcStatus);
236	        ScreenToClient(&rcStatus);
237	        canvasBottom = rcStatus.top;
238	
239	        const int dpi = static_cast<int>(GetDpiForWindow(m_hWnd));
240	        int parts[SP_COUNT] = {};
241	        const int widths[SP_COUNT - 1] = { 110, 110, 110, 60, 150 };
242	        int x = 0;
243	        for (int i = 0; i < SP_COUNT - 1; ++i)
244	        {
245	            x += MulDiv(widths[i], dpi, 96);
246	            parts[i] = x;
247	        }
248	        parts[SP_HINT] = -1;
249	        m_statusBar.SetParts(SP_COUNT, parts);
250	
251	        // 확대 슬라이더를 상태 표시줄의 슬라이더 칸 위에 올림
252	        CRect rcPart;
253	        m_statusBar.GetRect(SP_ZOOM_SLIDER, &rcPart);
254	        rcPart.OffsetRect(rcStatus.TopLeft());
255	        rcPart.DeflateRect(2, 1);
256	        m_zoomSlider.SetWindowPos(&wndTop, rcPart.left, rcPart.top, rcPart.Width(), rcPart.Height(), SWP_SHOWWINDOW);
257	    }
258	    else
259	    {
260	        m_zoomSlider.ShowWindow(SW_HIDE);
261	    }
262	
263	    // 캔버스는 도구 패널 오른쪽부터 상태 표시줄 위까지 채웁니다.
264	    CRect rcGroup;
265	    GetDlgItem(IDC_TOOL_GROUP)->GetWindowRect(&rcGroup);
266	    ScreenToClient(&rcGroup);
267	    const int left = rcGroup.right + rcGroup.left;
268	    m_canvas.MoveWindow(left, 0, std::max<int>(0, client.right - left), std::max(0, canvasBottom));
269	}
