315	void CMyPaintDlg::OnInitMenuPopup(CMenu* pPopupMenu, UINT nIndex, BOOL bSysMenu)
316	{
317	    CDialog::OnInitMenuPopup(pPopupMenu, nIndex, bSysMenu);
318	    if (bSysMenu)
319	        return;
320	
321	    // 대화 상자에는 ON_UPDATE_COMMAND_UI가 동작하지 않으므로 직접 켜고 끕니다.
322	    auto enable = [&](UINT id, bool on) {
323	        pPopupMenu->EnableMenuItem(id, MF_BYCOMMAND | (on ? MF_ENABLED : MF_GRAYED));
324	    };
325	    const bool hasSel = m_canvas.HasSelection();
326	    enable(ID_EDIT_UNDO_ACTION, m_canvas.CanUndo());
327	    enable(ID_EDIT_REDO_ACTION, m_canvas.CanRedo());
328	    enable(ID_EDIT_CUT_SEL, hasSel);
329	    enable(ID_EDIT_COPY_SEL, hasSel);
330	    enable(ID_EDIT_DELETE_SEL, hasSel);
