332	    enable(ID_IMAGE_CROP, hasSel);
333	    enable(ID_EDIT_INVERT_SEL, hasSel);
334	    RebuildRecentMenu(pPopupMenu); // "최근 파일" 하위 메뉴일 때만 다시 채움
335	    auto check = [&](UINT id, bool on) {
336	        pPopupMenu->CheckMenuItem(id, MF_BYCOMMAND | (on ? MF_CHECKED : MF_UNCHECKED));
337	    };
338	    check(ID_VIEW_STATUSBAR, m_statusVisible);
339	    check(ID_VIEW_RULERS, m_canvas.GetShowRulers());
