970	void CMyPaintDlg::OnOpenRecent(UINT nID)
971	{
972	    const size_t index = nID - ID_FILE_RECENT_FIRST;
973	    if (index >= m_recentFiles.size())
974	        return;
975	    const CString path = m_recentFiles[index];
976	    if (!ConfirmDiscardChanges())
977	        return;
978	    if (!OpenImageFile(path))
979	    {
980	        // 없어졌거나 열 수 없는 파일은 목록에서 뺌
981	        m_recentFiles.erase(m_recentFiles.begin() + static_cast<std::ptrdiff_t>(std::min(index, m_recentFiles.size() - 1)));
982	        SaveRecentFiles();
983	    }
984	}
