BOOL CMyPaintDlg::OnInitDialog()
{
    CDialog::OnInitDialog();

    SetIcon(m_hIcon, TRUE);  // 큰 아이콘
    SetIcon(m_hIcon, FALSE); // 작은 아이콘

    m_hAccel = ::LoadAccelerators(AfxGetResourceHandle(), MAKEINTRESOURCE(IDR_ACCEL));

    m_colorPanel.SubclassDlgItem(IDC_COLOR_PANEL, this);
    // WS_CLIPSIBLINGS: 상태 표시줄 위에 올린 확대 슬라이더를 덮어 그리지 않도록
    m_statusBar.Create(WS_CHILD | WS_VISIBLE | WS_CLIPSIBLINGS | SBARS_SIZEGRIP, CRect(0, 0, 0, 0), this, IDC_STATUSBAR);
    m_zoomSlider.Create(WS_CHILD | WS_VISIBLE | TBS_HORZ | TBS_NOTICKS | TBS_BOTH, CRect(0, 0, 0, 0), this, IDC_ZOOM_SLIDER);
    m_zoomSlider.SetRange(0, CCanvasWnd::ZoomLevelCount() - 1);
    m_canvas.Create(this, IDC_CANVAS);

    // 도형 옵션: 종류 목록, 윤곽선/채우기 (없음, 단색, 질감 5종)
    m_shapeCombo.Init();
    const int dpi = static_cast<int>(GetDpiForWindow(m_hWnd));
    for (CComboBox* combo : { &m_outlineCombo, &m_fillCombo })
    {
        for (int i = 0; i < kShapePaintCount; ++i)
            combo->AddString(ShapePaintName(static_cast<ShapePaint>(i)));
        combo->SetDroppedWidth(MulDiv(120, dpi, 96)); // 콤보가 좁아도 목록은 이름이 다 보이게
    }
    m_outlineCombo.SetCurSel(static_cast<int>(ShapePaint::Solid));
    m_fillCombo.SetCurSel(static_cast<int>(ShapePaint::None));
    m_canvas.SetShapeKind(m_shapeCombo.GetSelectedKind());
    m_canvas.SetShapeOptions(ShapePaint::Solid, ShapePaint::None);
    UpdateShapeControls();

    // 브러시 종류
    for (int i = 0; i < kBrushKindCount; ++i)
        m_brushCombo.AddString(BrushName(static_cast<BrushKind>(i)));
    m_brushCombo.SetCurSel(0);
    m_canvas.SetBrushKind(BrushKind::Normal);

    m_canvas.SetTool(ToolType::Pencil);
    m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
    SyncToolUi();

    m_canvas.NewImage(kDefaultWidth, kDefaultHeight);

    LayoutControls();
    UpdateTitle();
    UpdateStatusImageSize();
    UpdateStatusZoom();
    UpdateZoomSlider();

    DragAcceptFiles(TRUE); // 탐색기에서 그림 파일을 끌어다 놓으면 열기
    LoadRecentFiles();
    if (!m_startupFile.IsEmpty())
        OpenImageFile(m_startupFile);

    m_canvas.SetFocus();
    return FALSE; // 포커스를 직접 지정했음
}

BOOL CMyPaintDlg::PreTranslateMessage(MSG* pMsg)
{
    // 대화 상자는 단축키 테이블을 자동으로 처리하지 않으므로 직접 변환합니다.
    // 단, 글상자에 입력 중일 때는 Ctrl+C/V/Z, Del 등을 편집 컨트롤이 쓰도록 넘기고,
    // 전체 화면 창처럼 이 대화 상자 밖의 창으로 가는 키는 건드리지 않습니다.
    if (m_hAccel && pMsg->message >= WM_KEYFIRST && pMsg->message <= WM_KEYLAST
        && (pMsg->hwnd == m_hWnd || ::IsChild(m_hWnd, pMsg->hwnd))
        && !m_canvas.IsTextEditWindow(pMsg->hwnd)
        && ::TranslateAccelerator(m_hWnd, m_hAccel, pMsg))
    {
        return TRUE;
    }
    return CDialog::PreTranslateMessage(pMsg);
}

