CString CMyPaintDlg::DisplayName() const
{
    if (m_filePath.IsEmpty())
        return _T("제목 없음");
    return m_filePath.Mid(m_filePath.ReverseFind(_T('\\')) + 1);
}

void CMyPaintDlg::UpdateTitle()
{
    CString title;
    title.Format(_T("%s%s - MyPaint"), m_canvas.IsModified() ? _T("*") : _T(""), DisplayName().GetString());
    SetWindowText(title);
}

void CMyPaintDlg::UpdateStatusImageSize()
{
    if (!m_statusBar.GetSafeHwnd())
        return;
    const CSize size = m_canvas.GetImageSize();
    CString text;
    text.Format(_T("%d × %dpx"), size.cx, size.cy);
    m_statusBar.SetText(text, SP_IMAGE, 0);
}

void CMyPaintDlg::UpdateStatusZoom()
{
    if (!m_statusBar.GetSafeHwnd())
        return;
    CString text;
    text.Format(_T("%g%%"), m_canvas.GetZoom() * 100.0);
    m_statusBar.SetText(text, SP_ZOOM, 0);
}

void CMyPaintDlg::UpdateHint()
{
    if (!m_statusBar.GetSafeHwnd())
        return;

    CString hint;
    switch (m_canvas.GetTool())
    {
    case ToolType::Pencil:
        hint = _T("왼쪽 버튼: 색 1 · 오른쪽 버튼: 색 2 · Esc: 취소");
        break;
    case ToolType::Eraser:
        hint = _T("왼쪽: 색 2로 지우기 · 오른쪽: 색 1인 부분만 색 2로 바꾸기");
        break;
    case ToolType::Fill:
        hint = _T("왼쪽: 색 1로 채우기 · 오른쪽: 색 2로 채우기");
        break;
    case ToolType::Picker:
        hint = _T("왼쪽: 색 1로 지정 · 오른쪽: 색 2로 지정 (지정 후 직전 도구로 돌아감)");
        break;
    case ToolType::Text:
    {
        LOGFONT lf;
        int pt = 0;
        m_canvas.GetTextFont(lf, pt);
        hint.Format(_T("드래그/클릭: 글상자 · 바깥 클릭: 확정 · Esc: 취소 · 글꼴: %s %dpt"), lf.lfFaceName, pt);
        break;
    }
    case ToolType::Select:
    case ToolType::FreeSelect:
        hint = _T("드래그: 선택 · 안쪽 드래그: 이동 (Ctrl: 복사) · 핸들: 크기 조정 · 방향키: 1px 이동 · Del: 삭제 · Esc: 확정");
        break;
    case ToolType::Magnifier:
        hint = _T("왼쪽 클릭: 확대 · 오른쪽 클릭: 축소 (점선은 확대될 영역)");
        break;
    case ToolType::Shape:
        switch (m_canvas.GetShapeKind())
        {
        case ShapeKind::Curve:
            hint = _T("선을 그은 뒤 두 번 클릭/드래그해서 휘기 · Enter: 휘기 생략 · 그린 뒤 핸들로 조정");
            break;
        case ShapeKind::Polygon:
            hint = _T("클릭/드래그로 꼭짓점 추가 · 시작점 클릭/더블클릭/Enter: 닫기 · Esc: 취소");
            break;
        default:
            hint = _T("드래그: 그리기 (Shift: 정비율) · 그린 뒤 핸들로 크기/위치 조정 · 바깥 클릭/Esc/Enter: 확정");
            break;
        }
        break;
    case ToolType::Brush:
        hint.Format(_T("%s · 왼쪽 버튼: 색 1 · 오른쪽 버튼: 색 2 · Ctrl+Plus/Minus: 굵기 · Esc: 취소"),
                    BrushName(m_canvas.GetBrushKind()));
        break;
    default:
        hint = _T("왼쪽 버튼: 색 1 · 오른쪽 버튼: 색 2 · Esc: 취소");
        break;
    }
    m_statusBar.SetText(hint, SP_HINT, 0);
}

void CMyPaintDlg::SyncToolUi()
{
    const ToolType tool = m_canvas.GetTool();
    CheckRadioButton(IDC_TOOL_PENCIL, IDC_TOOL_MAGNIFIER, IDC_TOOL_PENCIL + static_cast<int>(tool));

    // 굵기 목록을 현재 도구의 픽셀 값으로 다시 채움
    const int level = m_canvas.GetSizeLevel();
    m_sizeCombo.ResetContent();
    for (int i = 0; i < kSizeLevelCount; ++i)
    {
        CString text;
        text.Format(_T("%d px"), CCanvasWnd::GetToolWidth(tool, i));
        m_sizeCombo.AddString(text);
    }
    m_sizeCombo.SetCurSel(level);
    const BOOL usesSize = CCanvasWnd::ToolUsesSize(tool) ? TRUE : FALSE;
    m_sizeCombo.EnableWindow(usesSize);
    GetDlgItem(IDC_SIZE_LABEL)->EnableWindow(usesSize);

    UpdateHint();
}

LRESULT CMyPaintDlg::OnCanvasNotify(WPARAM wParam, LPARAM lParam)
{
    switch (wParam)
    {
    case CN_CURSOR:
    case CN_SELSIZE:
        if (m_statusBar.GetSafeHwnd())
        {
            CString text;
            if (lParam != -1)
            {
                text.Format(wParam == CN_CURSOR ? _T("%d, %dpx") : _T("%d × %dpx"),
                            LOWORD(lParam), HIWORD(lParam));
            }
            m_statusBar.SetText(text, wParam == CN_CURSOR ? SP_CURSOR : SP_SELECTION, 0);
        }
        break;
    case CN_STATE:
        UpdateTitle();
        UpdateStatusImageSize();
        break;
    case CN_ZOOM:
        UpdateStatusZoom();
        UpdateZoomSlider();
        break;
    case CN_TOOL:
        SyncToolUi();
        break;
    case CN_PICK_COLOR1:
        m_colorPanel.SetColor1(static_cast<COLORREF>(lParam));
        m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
        break;
    case CN_PICK_COLOR2:
        m_colorPanel.SetColor2(static_cast<COLORREF>(lParam));
        m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
        break;
    }
    return 0;
}

LRESULT CMyPaintDlg::OnColorPanelChanged(WPARAM /*wParam*/, LPARAM /*lParam*/)
{
    m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
    m_canvas.FocusTextEdit(); // 글상자 입력 중이었다면 계속 입력할 수 있게
    return 0;
}

