void CMyPaintDlg::OnHScroll(UINT nSBCode, UINT nPos, CScrollBar* pScrollBar)
{
    if (pScrollBar && pScrollBar->GetSafeHwnd() == m_zoomSlider.GetSafeHwnd())
    {
        m_canvas.SetZoom(CCanvasWnd::ZoomLevelAt(m_zoomSlider.GetPos()));
        if (nSBCode == TB_ENDTRACK)
            m_canvas.SetFocus(); // 슬라이더를 놓으면 방향키가 다시 그림에 가도록
        return;
