    m_canvas.SetShapeKind(m_shapeCombo.GetSelectedKind());
    if (m_canvas.GetTool() != ToolType::Shape)
        m_canvas.SetTool(ToolType::Shape);
    UpdateShapeControls();
    SyncToolUi();
}

void CMyPaintDlg::OnShapeOptionsChanged()
{
    m_canvas.SetShapeOptions(static_cast<ShapePaint>(std::max(0, m_outlineCombo.GetCurSel())),
