127	BOOL CMyPaintDlg::OnInitDialog()
128	{
129	    CDialog::OnInitDialog();
130	
131	    SetIcon(m_hIcon, TRUE);  // 큰 아이콘
132	    SetIcon(m_hIcon, FALSE); // 작은 아이콘
133	
134	    m_hAccel = ::LoadAccelerators(AfxGetResourceHandle(), MAKEINTRESOURCE(IDR_ACCEL));
135	
136	    m_colorPanel.SubclassDlgItem(IDC_COLOR_PANEL, this);
137	    // WS_CLIPSIBLINGS: 상태 표시줄 위에 올린 확대 슬라이더를 덮어 그리지 않도록
138	    m_statusBar.Create(WS_CHILD | WS_VISIBLE | WS_CLIPSIBLINGS | SBARS_SIZEGRIP, CRect(0, 0, 0, 0), this, IDC_STATUSBAR);
139	    m_zoomSlider.Create(WS_CHILD | WS_VISIBLE | TBS_HORZ | TBS_NOTICKS | TBS_BOTH, CRect(0, 0, 0, 0), this, IDC_ZOOM_SLIDER);
140	    m_zoomSlider.SetRange(0, CCanvasWnd::ZoomLevelCount() - 1);
141	    m_canvas.Create(this, IDC_CANVAS);
142	
143	    // 도형 옵션: 종류 목록, 윤곽선/채우기 (없음, 단색, 질감 5종)
144	    m_shapeCombo.Init();
145	    const int dpi = static_cast<int>(GetDpiForWindow(m_hWnd));
146	    for (CComboBox* combo : { &m_outlineCombo, &m_fillCombo })
147	    {
148	        for (int i = 0; i < kShapePaintCount; ++i)
149	            combo->AddString(ShapePaintName(static_cast<ShapePaint>(i)));
150	        combo->SetDroppedWidth(MulDiv(120, dpi, 96)); // 콤보가 좁아도 목록은 이름이 다 보이게
151	    }
152	    m_outlineCombo.SetCurSel(static_cast<int>(ShapePaint::Solid));
153	    m_fillCombo.SetCurSel(static_cast<int>(ShapePaint::None));
154	    m_canvas.SetShapeKind(m_shapeCombo.GetSelectedKind());
155	    m_canvas.SetShapeOptions(ShapePaint::Solid, ShapePaint::None);
156	    UpdateShapeControls();
157	
158	    // 브러시 종류
159	    for (int i = 0; i < kBrushKindCount; ++i)
160	        m_brushCombo.AddString(BrushName(static_cast<BrushKind>(i)));
161	    m_brushCombo.SetCurSel(0);
162	    m_canvas.SetBrushKind(BrushKind::Normal);
163	
164	    m_canvas.SetTool(ToolType::Pencil);
165	    m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
166	    SyncToolUi();
167	
168	    m_canvas.NewImage(kDefaultWidth, kDefaultHeight);
169	
170	    LayoutControls();
171	    UpdateTitle();
172	    UpdateStatusImageSize();
173	    UpdateStatusZoom();
174	    UpdateZoomSlider();
175	
176	    DragAcceptFiles(TRUE); // 탐색기에서 그림 파일을 끌어다 놓으면 열기
177	    LoadRecentFiles();
178	    if (!m_startupFile.IsEmpty())
179	        OpenImageFile(m_startupFile);
180	
181	    m_canvas.SetFocus();
182	    return FALSE; // 포커스를 직접 지정했음
183	}
