185	BOOL CMyPaintDlg::PreTranslateMessage(MSG* pMsg)
186	{
187	    // 대화 상자는 단축키 테이블을 자동으로 처리하지 않으므로 직접 변환합니다.
188	    // 단, 글상자에 입력 중일 때는 Ctrl+C/V/Z, Del 등을 편집 컨트롤이 쓰도록 넘기고,
189	    // 전체 화면 창처럼 이 대화 상자 밖의 창으로 가는 키는 건드리지 않습니다.
190	    if (m_hAccel && pMsg->message >= WM_KEYFIRST && pMsg->message <= WM_KEYLAST
191	        && (pMsg->hwnd == m_hWnd || ::IsChild(m_hWnd, pMsg->hwnd))
192	        && !m_canvas.IsTextEditWindow(pMsg->hwnd)
193	        && ::TranslateAccelerator(m_hWnd, m_hAccel, pMsg))
194	    {
195	        return TRUE;
196	    }
197	    return CDialog::PreTranslateMessage(pMsg);
198	}
