291	void CMyPaintDlg::OnGetMinMaxInfo(MINMAXINFO* lpMMI)
292	{
293	    CDialog::OnGetMinMaxInfo(lpMMI);
294	    if (!GetSafeHwnd() || !m_colorPanel.GetSafeHwnd())
295	        return;
296	
297	    // 왼쪽 패널(색 패널 아래 끝)이 잘리지 않을 만큼의 높이를 최소 크기로
298	    const int dpi = static_cast<int>(GetDpiForWindow(m_hWnd));
299	    CRect rcPanel;
300	    m_colorPanel.GetWindowRect(&rcPanel);
301	    ScreenToClient(&rcPanel);
