303	    if (m_statusVisible && m_statusBar.GetSafeHwnd())
304	    {
305	        CRect rcStatus;
306	        m_statusBar.GetWindowRect(&rcStatus);
307	        clientHeight += rcStatus.Height();
308	    }
309	    CRect rc(0, 0, MulDiv(640, dpi, 96), clientHeight);
310	    AdjustWindowRectEx(&rc, GetStyle(), TRUE, GetExStyle());
311	    lpMMI->ptMinTrackSize.x = rc.Width();
312	    lpMMI->ptMinTrackSize.y = rc.Height();
313	}
