381	void CMyPaintDlg::UpdateHint()
382	{
383	    if (!m_statusBar.GetSafeHwnd())
384	        return;
385	
386	    CString hint;
387	    switch (m_canvas.GetTool())
388	    {
389	    case ToolType::Pencil:
390	        hint = _T("왼쪽 버튼: 색 1 · 오른쪽 버튼: 색 2 · Esc: 취소");
391	        break;
392	    case ToolType::Eraser:
393	        hint = _T("왼쪽: 색 2로 지우기 · 오른쪽: 색 1인 부분만 색 2로 바꾸기");
394	        break;
395	    case ToolType::Fill:
396	        hint = _T("왼쪽: 색 1로 채우기 · 오른쪽: 색 2로 채우기");
397	        break;
398	    case ToolType::Picker:
399	        hint = _T("왼쪽: 색 1로 지정 · 오른쪽: 색 2로 지정 (지정 후 직전 도구로 돌아감)");
400	        break;
401	    case ToolType::Text:
402	    {
403	        LOGFONT lf;
404	        int pt = 0;
405	        m_canvas.GetTextFont(lf, pt);
406	        hint.Format(_T("드래그/클릭: 글상자 · 바깥 클릭: 확정 · Esc: 취소 · 글꼴: %s %dpt"), lf.lfFaceName, pt);
407	        break;
408	    }
409	    case ToolType::Select:
410	    case ToolType::FreeSelect:
411	        hint = _T("드래그: 선택 · 안쪽 드래그: 이동 (Ctrl: 복사) · 핸들: 크기 조정 · 방향키: 1px 이동 · Del: 삭제 · Esc: 확정");
412	        break;
413	    case ToolType::Magnifier:
414	        hint = _T("왼쪽 클릭: 확대 · 오른쪽 클릭: 축소 (점선은 확대될 영역)");
415	        break;
416	    case ToolType::Shape:
417	        switch (m_canvas.GetShapeKind())
418	        {
419	        case ShapeKind::Curve:
420	            hint = _T("선을 그은 뒤 두 번 클릭/드래그해서 휘기 · Enter: 휘기 생략 · 그린 뒤 핸들로 조정");
421	            break;
422	        case ShapeKind::Polygon:
423	            hint = _T("클릭/드래그로 꼭짓점 추가 · 시작점 클릭/더블클릭/Enter: 닫기 · Esc: 취소");
424	            break;
425	        default:
426	            hint = _T("드래그: 그리기 (Shift: 정비율) · 그린 뒤 핸들로 크기/위치 조정 · 바깥 클릭/Esc/Enter: 확정");
427	            break;
428	        }
429	        break;
430	    case ToolType::Brush:
431	        hint.Format(_T("%s · 왼쪽 버튼: 색 1 · 오른쪽 버튼: 색 2 · Ctrl+Plus/Minus: 굵기 · Esc: 취소"),
432	                    BrushName(m_canvas.GetBrushKind()));
433	        break;
434	    default:
435	        hint = _T("왼쪽 버튼: 색 1 · 오른쪽 버튼: 색 2 · Esc: 취소");
436	        break;
437	    }
438	    m_statusBar.SetText(hint, SP_HINT, 0);
439	}
