441	void CMyPaintDlg::SyncToolUi()
442	{
443	    const ToolType tool = m_canvas.GetTool();
444	    CheckRadioButton(IDC_TOOL_PENCIL, IDC_TOOL_MAGNIFIER, IDC_TOOL_PENCIL + static_cast<int>(tool));
445	
446	    // 굵기 목록을 현재 도구의 픽셀 값으로 다시 채움
447	    const int level = m_canvas.GetSizeLevel();
448	    m_sizeCombo.ResetContent();
449	    for (int i = 0; i < kSizeLevelCount; ++i)
450	    {
451	        CString text;
452	        text.Format(_T("%d px"), CCanvasWnd::GetToolWidth(tool, i));
453	        m_sizeCombo.AddString(text);
