455	    m_sizeCombo.SetCurSel(level);
456	    const BOOL usesSize = CCanvasWnd::ToolUsesSize(tool) ? TRUE : FALSE;
457	    m_sizeCombo.EnableWindow(usesSize);
458	    GetDlgItem(IDC_SIZE_LABEL)->EnableWindow(usesSize);
459	
460	    UpdateHint();
461	}
