463	LRESULT CMyPaintDlg::OnCanvasNotify(WPARAM wParam, LPARAM lParam)
464	{
465	    switch (wParam)
466	    {
467	    case CN_CURSOR:
468	    case CN_SELSIZE:
469	        if (m_statusBar.GetSafeHwnd())
470	        {
471	            CString text;
472	            if (lParam != -1)
473	            {
474	                text.Format(wParam == CN_CURSOR ? _T("%d, %dpx") : _T("%d × %dpx"),
475	                            LOWORD(lParam), HIWORD(lParam));
476	            }
477	            m_statusBar.SetText(text, wParam == CN_CURSOR ? SP_CURSOR : SP_SELECTION, 0);
478	        }
479	        break;
480	    case CN_STATE:
481	        UpdateTitle();
482	        UpdateStatusImageSize();
483	        break;
484	    case CN_ZOOM:
485	        UpdateStatusZoom();
486	        UpdateZoomSlider();
487	        break;
488	    case CN_TOOL:
489	        SyncToolUi();
490	        break;
491	    case CN_PICK_COLOR1:
492	        m_colorPanel.SetColor1(static_cast<COLORREF>(lParam));
493	        m_canvas.SetColors(m_colorPanel.GetColor1(), m_colorPanel.GetColor2());
494	        break;
