795	bool CMyPaintDlg::ConfirmDiscardChanges()
796	{
797	    m_canvas.FinishPendingWork(); // 입력 중인 글, 떠 있는 선택 영역도 변경 내용에 포함
798	    if (!m_canvas.IsModified())
799	        return true;
800	
801	    CString msg;
802	    msg.Format(_T("변경 내용을 %s에 저장하시겠습니까?"), DisplayName().GetString());
803	    switch (MessageBox(msg, _T("MyPaint"), MB_YESNOCANCEL | MB_ICONWARNING))
804	    {
805	    case IDYES:
806	        return m_filePath.IsEmpty() ? SaveAsWithDialog() : SaveTo(m_filePath);
807	    case IDNO:
808	        return true;
809	    default:
810	        return false;
811	    }
812	}
