814	bool CMyPaintDlg::SaveTo(const CString& path)
815	{
816	    const HRESULT hr = m_canvas.SaveToFile(path);
817	    if (FAILED(hr))
818	    {
819	        CString msg;
820	        msg.Format(_T("파일을 저장하지 못했습니다.\n%s\n\n지원 형식: PNG, BMP, JPEG, GIF, TIFF (오류 코드 0x%08X)"),
821	                   path.GetString(), static_cast<unsigned>(hr));
822	        MessageBox(msg, _T("MyPaint"), MB_OK | MB_ICONERROR);
823	        return false;
824	    }
825	    m_filePath = path;
826	    m_canvas.SetModified(false); // CN_STATE 알림으로 제목도 갱신됨
827	    AddRecentFile(path);
828	    return true;
829	}
