929	void CMyPaintDlg::AddRecentFile(const CString& path)
930	{
931	    // 이미 있으면 맨 앞으로, 넘치면 오래된 것부터 버림
932	    m_recentFiles.erase(std::remove_if(m_recentFiles.begin(), m_recentFiles.end(),
933	                                       [&](const CString& p) { return p.CompareNoCase(path) == 0; }),
934	                        m_recentFiles.end());
935	    m_recentFiles.insert(m_recentFiles.begin(), path);
936	    if (static_cast<int>(m_recentFiles.size()) > kMaxRecentFiles)
937	        m_recentFiles.resize(kMaxRecentFiles);
938	    SaveRecentFiles();
939	}
