941	void CMyPaintDlg::RebuildRecentMenu(CMenu* pMenu) const
942	{
943	    // "최근 파일" 하위 메뉴인지: 첫 항목이 (없음) 또는 최근 파일 ID
944	    if (!pMenu || pMenu->GetMenuItemCount() == 0)
945	        return;
946	    const UINT firstId = pMenu->GetMenuItemID(0);
947	    if (firstId != ID_FILE_RECENT_NONE && (firstId < ID_FILE_RECENT_FIRST || firstId > ID_FILE_RECENT_LAST))
948	        return;
949	
950	    while (pMenu->GetMenuItemCount() > 0)
951	        pMenu->DeleteMenu(0, MF_BYPOSITION);
952	    if (m_recentFiles.empty())
953	    {
954	        pMenu->AppendMenu(MF_STRING | MF_GRAYED, ID_FILE_RECENT_NONE, _T("(없음)"));
955	        return;
956	    }
957	    for (size_t i = 0; i < m_recentFiles.size(); ++i)
958	    {
959	        // 긴 경로는 가운데를 ...로 줄이고, 메뉴에서 &가 밑줄로 바뀌지 않게 &&로
960	        TCHAR compact[MAX_PATH] = {};
961	        ::PathCompactPathEx(compact, m_recentFiles[i], 60, 0);
962	        CString name(compact);
963	        name.Replace(_T("&"), _T("&&"));
964	        CString text;
965	        text.Format(_T("&%d %s"), static_cast<int>(i) + 1, name.GetString());
966	        pMenu->AppendMenu(MF_STRING, ID_FILE_RECENT_FIRST + static_cast<UINT>(i), text);
967	    }
968	}
969	
970	void CMyPaintDlg::OnOpenRecent(UINT nID)
971	{
972	    const size_t index = nID - ID_FILE_RECENT_FIRST;
973	    if (index >= m_recentFiles.size())
974	        return;
975	    const CString path = m_recentFiles[index];
976	    if (!ConfirmDiscardChanges())
977	        return;
978	    if (!OpenImageFile(path))
979	    {
980	        // 없어졌거나 열 수 없는 파일은 목록에서 뺌
981	        m_recentFiles.erase(m_recentFiles.begin() + static_cast<std::ptrdiff_t>(std::min(index, m_recentFiles.size() - 1)));
982	        SaveRecentFiles();
983	    }
984	}
