1001	    }
1002	
1003	    const DESKTOP_WALLPAPER_POSITION position = nID == ID_FILE_WALLPAPER_TILE ? DWPOS_TILE
1004	                                              : nID == ID_FILE_WALLPAPER_CENTER ? DWPOS_CENTER : DWPOS_FILL;
1005	    const HRESULT hrInit = ::CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
1006	    HRESULT hr = E_FAIL;
1007	    {
1008	        CComPtr<IDesktopWallpaper> wallpaper;
1009	        hr = wallpaper.CoCreateInstance(CLSID_DesktopWallpaper);
1010	        if (SUCCEEDED(hr))
1011	            hr = wallpaper->SetPosition(position);
1012	        if (SUCCEEDED(hr))
1013	            hr = wallpaper->SetWallpaper(nullptr, m_filePath); // nullptr: 모든 모니터
1014	    }
1015	    if (SUCCEEDED(hrInit))
1016	        ::CoUninitialize();
1017	
1018	    if (FAILED(hr))
1019	    {
1020	        CString msg;
1021	        msg.Format(_T("바탕 화면 배경으로 설정하지 못했습니다.\n%s\n\n(오류 코드 0x%08X)"),
1022	                   m_filePath.GetString(), static_cast<unsigned>(hr));
1023	        MessageBox(msg, _T("MyPaint"), MB_OK | MB_ICONERROR);
1024	    }
1025	}
1026	
1027	void CMyPaintDlg::OnFileSave()
1028	{
1029	    m_canvas.FinishPendingWork();
1030	    if (m_filePath.IsEmpty())
1031	        SaveAsWithDialog();
1032	    else
1033	        SaveTo(m_filePath);
1034	}
