    ON_COMMAND_RANGE(ID_COLOR_EDIT1, ID_COLOR_EDIT2, &CMyPaintDlg::OnColorEdit)
    ON_COMMAND(ID_TEXT_FONT_CMD, &CMyPaintDlg::OnTextFont)
