param([string]$Exe, [string]$Dir)
Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Text;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public static class U {
  public delegate bool EnumProc(IntPtr h, IntPtr l);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc f, IntPtr l);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] public static extern IntPtr GetDlgItem(IntPtr h, int id);
  [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr h, uint m, IntPtr w, IntPtr l);
  [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h, uint m, IntPtr w, IntPtr l);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h, IntPtr hdc, uint flags);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern IntPtr GetProp(IntPtr h, string name);
  [DllImport("user32.dll")] public static extern bool RedrawWindow(IntPtr h, IntPtr r, IntPtr rgn, uint flags);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int L, T, R, B; }
  public static List<IntPtr> Windows(uint pid) {
    var list = new List<IntPtr>();
    EnumWindows((h, l) => { uint p; GetWindowThreadProcessId(h, out p); if (p == pid && IsWindowVisible(h)) list.Add(h); return true; }, IntPtr.Zero);
    return list;
  }
}
"@
function Shot($hwnd, $file) {
  [U]::RedrawWindow($hwnd, [IntPtr]::Zero, [IntPtr]::Zero, 0x0185) | Out-Null
  Start-Sleep -Milliseconds 1500
  $r = New-Object U+RECT; [U]::GetWindowRect($hwnd, [ref]$r) | Out-Null
  $bmp = New-Object System.Drawing.Bitmap ($r.R - $r.L), ($r.B - $r.T)
  $g = [System.Drawing.Graphics]::FromImage($bmp); $hdc = $g.GetHdc(); [U]::PrintWindow($hwnd, $hdc, 2) | Out-Null; $g.ReleaseHdc($hdc); $g.Dispose()
  $bmp.Save((Join-Path $Dir $file)); $bmp.Dispose()
}
function MK([int]$x, [int]$y) { [IntPtr](($y -shl 16) -bor ($x -band 0xFFFF)) }
$p = Start-Process -FilePath $Exe -PassThru
Start-Sleep -Milliseconds 1800; $p.Refresh()
$h = $p.MainWindowHandle
$canvas = [U]::GetDlgItem($h, 1030); $bar = [U]::GetDlgItem($h, 1033)
# 무언가 그리기: 도형(별) + 브러시
"tool0=" + [int][U]::GetProp($h,'MyPaint.Tool')
[U]::SendMessage($h, 0x111, [IntPtr]32856, [IntPtr]0) | Out-Null   # 5각 별 (ID_SHAPE_FIRST + 16)
"tool1=" + [int][U]::GetProp($h,'MyPaint.Tool')
[U]::SendMessage($h, 0x111, [IntPtr]32881, [IntPtr]0) | Out-Null   # 채우기 단색
[U]::SendMessage($h, 0x111, [IntPtr]32933, [IntPtr]0) | Out-Null   # 색 2 = 빨강 (팔레트 3)
[U]::SendMessage($canvas, 0x201, [IntPtr]1, (MK 100 80)) | Out-Null
[U]::SendMessage($canvas, 0x200, [IntPtr]1, (MK 260 230)) | Out-Null
[U]::SendMessage($canvas, 0x202, [IntPtr]0, (MK 260 230)) | Out-Null
"tool2=" + [int][U]::GetProp($h,'MyPaint.Tool')
Shot $h 'ui_main.png'
# 텍스트 도구
[U]::SendMessage($h, 0x111, [IntPtr]1005, [IntPtr]0) | Out-Null
Shot $h 'ui_text.png'
[U]::SendMessage($h, 0x111, [IntPtr]1008, [IntPtr]0) | Out-Null   # 도형 도구로
# 도형 전체 보기 드롭다운
$before = [U]::Windows([uint32]$p.Id)
[U]::PostMessage($bar, 0x201, [IntPtr]1, (MK 516 60)) | Out-Null
Start-Sleep -Milliseconds 800
$popup = [U]::Windows([uint32]$p.Id) | Where-Object { $before -notcontains $_ } | Select-Object -First 1
if ($popup) { Shot $popup 'ui_popup_shapes.png'; "popup ok" } else { "no popup" }
[U]::PostMessage($h, 0x100, [IntPtr]0x1B, [IntPtr]0) | Out-Null
Start-Sleep -Milliseconds 400
# 브러시 드롭다운 (브러시 버튼 아래쪽)
$before = [U]::Windows([uint32]$p.Id)
[U]::PostMessage($bar, 0x201, [IntPtr]1, (MK 298 82)) | Out-Null
Start-Sleep -Milliseconds 800
$popup = [U]::Windows([uint32]$p.Id) | Where-Object { $before -notcontains $_ } | Select-Object -First 1
if ($popup) { Shot $popup 'ui_popup_brush.png'; "brush popup ok" } else { "no brush popup" }
[U]::PostMessage($h, 0x100, [IntPtr]0x1B, [IntPtr]0) | Out-Null
Start-Sleep -Milliseconds 400
# 파일 메뉴 (메뉴 줄)
$before = [U]::Windows([uint32]$p.Id)
[U]::PostMessage($bar, 0x201, [IntPtr]1, (MK 37 16)) | Out-Null
Start-Sleep -Milliseconds 1200
$menu = [U]::Windows([uint32]$p.Id) | Where-Object { $before -notcontains $_ } | Select-Object -First 1
if ($menu) {
  $r = New-Object U+RECT; [U]::GetWindowRect($h, [ref]$r) | Out-Null
  $m = New-Object U+RECT; [U]::GetWindowRect($menu, [ref]$m) | Out-Null
  $x0 = [Math]::Min($r.L, $m.L); $y0 = [Math]::Min($r.T, $m.T); $x1 = [Math]::Max($m.R, $r.L + 500); $y1 = [Math]::Max($m.B, $r.T + 200)
  $bmp = New-Object System.Drawing.Bitmap ($x1 - $x0), ($y1 - $y0)
  $g = [System.Drawing.Graphics]::FromImage($bmp); $g.CopyFromScreen($x0, $y0, 0, 0, $bmp.Size); $g.Dispose()
  $bmp.Save((Join-Path $Dir 'ui_menu.png')); $bmp.Dispose(); "menu ok"
} else { "no menu" }
[U]::PostMessage($h, 0x100, [IntPtr]0x1B, [IntPtr]0) | Out-Null
Start-Sleep -Milliseconds 400
$p | Stop-Process -Force

