479	     * @brief 선택 윤곽선 고리들 (m_selRect 왼쪽 위 기준 상대 좌표)
480	     * 1개: 자유형 선택 (안쪽 전부). 2개 이상: 반전 선택 (교대 채우기 = 바깥 테두리 안, 원래 윤곽 밖)
481	     */
482	    std::vector<std::vector<CPoint>> m_selRings;
483	    int m_selHandle = -1;                       ///< 끌고 있는 선택 영역 핸들
484	    CRect m_selDragStartRect;                   ///< 핸들 드래그 시작 시 선택 영역
485	    PixelBuffer m_selDragSource;                ///< 핸들 드래그 시작 시 떠 있는 그림 원본
486	    std::vector<std::vector<CPoint>> m_selDragRings; ///< 핸들 드래그 시작 시 윤곽선
487	    std::vector<CPoint> m_lasso; ///< 자유형 선택 드래그 중인 경로 (이미지 좌표)
488	    bool m_floating = false;     ///< 선택 영역의 그림을 떼어 낸 상태인지
489	    CImage m_floatSource;        ///< 떠 있는 그림 원본 (미리 곱한 알파: 선택 밖은 투명)
490	    CImage m_floatImage;         ///< 화면 표시·찍기용 = 원본 + 투명 선택 적용
491	    bool m_transparentSelection = false;
492	    CPoint m_moveGrab;           ///< 이동 시 잡은 점과 선택 영역 왼쪽 위의 차이
493	
494	    // 텍스트
495	    CTextEdit m_textEdit;        ///< 글상자 입력 창 (캔버스의 자식)
496	    CFont m_textEditFont;        ///< 입력 창용 글꼴 (확대 배율 적용)
497	    CBrush m_textBrush;          ///< 입력 창 배경 브러시 (색 2)
498	    bool m_textActive = false;
499	    CRect m_textRect;            ///< 글상자 (이미지 좌표)
500	    int m_textMinHeight = 0;     ///< 사용자가 지정한 글상자 높이
501	    LOGFONT m_textLogFont{};
502	    int m_textPointSize = 12;
503	    bool m_textTransparent = false;
504	
505	    // 브러시
506	    BrushKind m_brushKind = BrushKind::Normal;
507	    CBrushStroke m_brushStroke;
508	
509	    // 화면
510	    bool m_showRulers = false;
511	    bool m_showGrid = false;
512	    double m_zoom = 1.0;
513	    CPoint m_scroll;             ///< 스크롤 위치 (화면 픽셀)
514	    bool m_updatingScroll = false;
515	    bool m_trackingMouse = false;
516	    bool m_hoverValid = false;   ///< 지우개 미리 보기용 마우스 위치가 유효한지
517	    CPoint m_hoverPt;            ///< 마우스 위치 (이미지 좌표)
518	    LPARAM m_lastCursorNotify = -2;
519	    LPARAM m_lastSelSizeNotify = -2;
520	};
