400	bool CCanvasWnd::Paste()
401	{
402	    CImage clip;
403	    if (!ReadClipboard(clip))
404	        return false;
405	
406	    ChangeToolInternal(ToolType::Select); // 진행 중인 작업 확정 후 선택 도구로
407	
408	    ImageSnapshot before = CaptureSnapshot();
409	    const CSize size = GetImageSize();
410	    if (clip.GetWidth() > size.cx || clip.GetHeight() > size.cy)
411	    {
412	        const int answer = MessageBox(
413	            _T("붙여넣는 그림이 캔버스보다 큽니다.\n캔버스를 그림 크기에 맞게 늘릴까요?"),
414	            _T("MyPaint"), MB_YESNOCANCEL | MB_ICONQUESTION);
415	        if (answer == IDCANCEL)
416	            return false;
417	        if (answer == IDYES)
418	            ResizeCanvasTo(CSize(std::max<int>(size.cx, clip.GetWidth()), std::max<int>(size.cy, clip.GetHeight())), false);
419	    }
420	    m_history.Push(std::move(before)); // 캔버스 늘리기와 붙여넣기를 한 단계로
421	
422	    // 지금 화면에 보이는 영역의 왼쪽 위에 붙여넣습니다.
423	    CPoint topLeft = ClientToImage(CPoint(0, 0));
424	    topLeft.x = std::max<int>(0, topLeft.x);
425	    topLeft.y = std::max<int>(0, topLeft.y);
426	
427	    m_selRect = CRect(topLeft, CSize(clip.GetWidth(), clip.GetHeight()));
428	    m_selFreeform = false;
429	    ReplaceImage(m_floatSource, clip);
430	    RebuildFloatImage();
431	    m_floating = true;
432	    m_hasSelection = true;
433	    Invalidate(FALSE);
434	    NotifySelectionSize();
435	    MarkModified();
436	    return true;
437	}
