439	bool CCanvasWnd::WriteClipboard(CImage& source)
440	{
441	    // 대부분의 프로그램이 읽을 수 있는 24비트 CF_DIB(아래→위 순서)로 올립니다.
442	    // 투명한 부분(자유형 선택 밖)은 색 2 위에 합성합니다.
443	    const int width = source.GetWidth();
444	    const int height = source.GetHeight();
445	    if (width <= 0 || height <= 0)
446	        return false;
447	
448	    const int stride = (width * 3 + 3) & ~3;
449	    const size_t bytes = sizeof(BITMAPINFOHEADER) + static_cast<size_t>(stride) * height;
450	    HGLOBAL hMem = ::GlobalAlloc(GMEM_MOVEABLE, bytes);
451	    if (!hMem)
452	        return false;
453	
454	    auto* bih = static_cast<BITMAPINFOHEADER*>(::GlobalLock(hMem));
455	    ZeroMemory(bih, sizeof(BITMAPINFOHEADER));
456	    bih->biSize = sizeof(BITMAPINFOHEADER);
457	    bih->biWidth = width;
458	    bih->biHeight = height; // 양수: 아래→위
459	    bih->biPlanes = 1;
460	    bih->biBitCount = 24;
461	    bih->biCompression = BI_RGB;
462	    bih->biSizeImage = static_cast<DWORD>(stride) * height;
463	
464	    GdiFlush();
465	    const uint32_t background = ToPixel(m_color2);
466	    BYTE* bits = reinterpret_cast<BYTE*>(bih + 1);
467	    for (int y = 0; y < height; ++y)
468	    {
469	        const auto* src = static_cast<const uint32_t*>(source.GetPixelAddress(0, y));
470	        BYTE* dst = bits + static_cast<size_t>(height - 1 - y) * stride;
471	        for (int x = 0; x < width; ++x)
472	        {
473	            const uint32_t p = BlendOver(background, src[x]);
474	            dst[x * 3 + 0] = static_cast<BYTE>(p & 0xFF);         // B
475	            dst[x * 3 + 1] = static_cast<BYTE>((p >> 8) & 0xFF);  // G
476	            dst[x * 3 + 2] = static_cast<BYTE>((p >> 16) & 0xFF); // R
477	        }
478	    }
479	    ::GlobalUnlock(hMem);
480	
481	    if (!OpenClipboardWithRetry(m_hWnd))
482	    {
483	        ::GlobalFree(hMem);
484	        return false;
485	    }
486	    ::EmptyClipboard();
487	    const bool ok = ::SetClipboardData(CF_DIB, hMem) != nullptr;
488	    ::CloseClipboard();
489	    if (!ok)
490	        ::GlobalFree(hMem); // 성공하면 메모리는 클립보드 소유
491	    return ok;
492	}
