494	bool CCanvasWnd::ReadClipboard(CImage& out)
495	{
496	    if (!CanPaste() || !OpenClipboardWithRetry(m_hWnd))
497	        return false;
498	
499	    // CF_DIB만 있어도 시스템이 CF_BITMAP을 만들어 주므로 CF_BITMAP 하나로 읽습니다.
500	    bool ok = false;
501	    auto hBitmap = static_cast<HBITMAP>(::GetClipboardData(CF_BITMAP));
502	    BITMAP bm{};
503	    if (hBitmap && ::GetObject(hBitmap, sizeof(bm), &bm) && bm.bmWidth > 0 && bm.bmHeight > 0
504	        && CreateDib32(out, bm.bmWidth, bm.bmHeight, RGB(255, 255, 255)))
505	    {
506	        CDC src;
507	        src.CreateCompatibleDC(nullptr);
508	        HGDIOBJ old = ::SelectObject(src.GetSafeHdc(), hBitmap);
509	        HDC hdc = out.GetDC();
510	        ::BitBlt(hdc, 0, 0, bm.bmWidth, bm.bmHeight, src.GetSafeHdc(), 0, 0, SRCCOPY);
511	        out.ReleaseDC();
512	        ::SelectObject(src.GetSafeHdc(), old); // 클립보드 소유 비트맵이므로 삭제하지 않음
513	        ok = true;
514	    }
515	    ::CloseClipboard();
516	
517	    if (ok)
518	    {
519	        // 떠 있는 그림으로 쓰므로 전부 불투명(알파 255)으로
520	        GdiFlush();
521	        for (int y = 0; y < out.GetHeight(); ++y)
522	        {
523	            auto* row = static_cast<uint32_t*>(out.GetPixelAddress(0, y));
524	            for (int x = 0; x < out.GetWidth(); ++x)
525	                row[x] |= 0xFF000000;
526	        }
527	    }
528	    return ok;
529	}
