538	std::vector<CRect> CCanvasWnd::SelectionHandleRects() const
539	{
540	    if (!m_hasSelection || (m_tool != ToolType::Select && m_tool != ToolType::FreeSelect))
541	        return {};
542	    if (m_dragMode != DragMode::None && m_dragMode != DragMode::SelectionHandle)
543	        return {};
544	    CRect box = ImageToClient(m_selRect);
