176	void CTopBar::AddGroups()
177	{
178	    const int top = m_menuHeight + Px(4);
179	    const int bottom = top + Px(kContent);
180	    const int gap = Px(14);
181	    int x = Px(10);
182	
183	    auto glyphIcon = [](wchar_t g) { Icon i; i.glyph = g; return i; };
184	    auto drawnIcon = [](theme::DrawnIcon d) { Icon i; i.drawn = true; i.shape = d; return i; };
185	    auto add = [&](Kind kind, const CRect& rc, UINT cmd, Popup popup, Icon icon, LPCTSTR label, LPCTSTR tip, int index = -1) {
186	        Item it;
187	        it.kind = kind; it.rc = rc; it.command = cmd; it.popup = popup; it.icon = icon;
188	        it.label = label; it.tip = tip; it.index = index;
189	        m_items.push_back(it);
190	    };
191	    auto group = [&](LPCTSTR name, int left, int right) {
192	        m_groups.push_back({ name, CRect(left - Px(6), top, right + Px(6), bottom + Px(2) + Px(kGroupLabel)) });
193	        x = right + gap;
194	    };
195	    const int bw = Px(32), bh = Px(29);              // 작은 버튼
196	    const int row1 = top + Px(1), row2 = top + Px(31);
197	
198	    // [선택]
199	    {
200	        const int left = x;
201	        add(Kind::Large, CRect(x, top, x + Px(52), bottom), IDC_TOOL_SELECT, Popup::Selection,
202	            drawnIcon(theme::DrawnIcon::RectSelect), _T("선택"), _T("선택 (아래쪽: 선택 방식, 모두 선택, 반전, 투명 선택)"));
203	        group(_T("선택"), left, x + Px(52));
204	    }
205	    // [이미지]
206	    {
207	        const int left = x;
208	        add(Kind::Small, CRect(x, row1, x + bw, row1 + bh), ID_IMAGE_CROP, Popup::None, glyphIcon(theme::kGlyphCrop), _T(""), _T("자르기 (Ctrl+Shift+X)"));
209	        add(Kind::Small, CRect(x + bw + Px(2), row1, x + bw * 2 + Px(2), row1 + bh), ID_IMAGE_RESIZE_SKEW, Popup::None,
210	            glyphIcon(theme::kGlyphResize), _T(""), _T("크기 조정 및 기울이기 (Ctrl+W)"));
211	        add(Kind::Labeled, CRect(x, row2, x + bw * 2 + Px(2), row2 + bh), 0, Popup::Rotate, glyphIcon(theme::kGlyphRotate), _T(""), _T("회전 / 대칭"));
212	        group(_T("이미지"), left, x + bw * 2 + Px(2));
213	    }
214	    // [도구]
215	    {
216	        const int left = x;
217	        struct T { UINT id; Icon icon; LPCTSTR tip; };
218	        const T tools[6] = {
219	            { IDC_TOOL_PENCIL, glyphIcon(theme::kGlyphPencil), _T("연필") },
220	            { IDC_TOOL_FILL, drawnIcon(theme::DrawnIcon::Bucket), _T("채우기") },
221	            { IDC_TOOL_TEXT, glyphIcon(theme::kGlyphText), _T("텍스트") },
222	            { IDC_TOOL_ERASER, glyphIcon(theme::kGlyphEraser), _T("지우개") },
223	            { IDC_TOOL_PICKER, glyphIcon(theme::kGlyphPicker), _T("스포이트") },
224	            { IDC_TOOL_MAGNIFIER, glyphIcon(theme::kGlyphZoom), _T("돋보기") },
225	        };
226	        for (int i = 0; i < 6; ++i)
227	        {
228	            const int cx = x + (i % 3) * (bw + Px(2));
229	            const int cy = (i < 3) ? row1 : row2;
230	            add(Kind::Small, CRect(cx, cy, cx + bw, cy + bh), tools[i].id, Popup::None, tools[i].icon, _T(""), tools[i].tip);
231	        }
232	        group(_T("도구"), left, x + bw * 3 + Px(4));
233	    }
234	
235	    if (m_textMode)
236	    {
237	        // [텍스트] 글꼴 / 굵게·기울임·밑줄 / 배경 투명
238	        const int left = x;
239	        const int w = Px(170);
240	        add(Kind::Labeled, CRect(x, row1, x + w, row1 + bh), ID_TEXT_FONT_CMD, Popup::None, glyphIcon(theme::kGlyphFont),
241	            m_state.fontLabel, _T("글꼴 (글꼴, 크기, 효과, 색)"));
242	        add(Kind::Small, CRect(x, row2, x + bw, row2 + bh), ID_TEXT_BOLD_CMD, Popup::None, glyphIcon(theme::kGlyphBold), _T(""), _T("굵게 (Ctrl+B)"));
243	        add(Kind::Small, CRect(x + bw + Px(2), row2, x + bw * 2 + Px(2), row2 + bh), ID_TEXT_ITALIC_CMD, Popup::None,
244	            glyphIcon(theme::kGlyphItalic), _T(""), _T("기울임 (Ctrl+I)"));
245	        add(Kind::Small, CRect(x + (bw + Px(2)) * 2, row2, x + bw * 3 + Px(4), row2 + bh), ID_TEXT_UNDERLINE_CMD, Popup::None,
246	            glyphIcon(theme::kGlyphUnderline), _T(""), _T("밑줄 (Ctrl+U)"));
247	        add(Kind::Labeled, CRect(x + bw * 3 + Px(10), row2, x + w, row2 + bh), ID_TEXT_TRANSPARENT_CMD, Popup::None, Icon(),
248	            _T("배경 투명"), _T("배경 투명: 끄면 글상자를 색 2로 채움"));
249	        group(_T("텍스트"), left, x + w);
250	    }
251	    else
252	    {
253	        // [브러시]
254	        {
255	            const int left = x;
256	            add(Kind::Large, CRect(x, top, x + Px(56), bottom), IDC_TOOL_BRUSH, Popup::Brush, glyphIcon(theme::kGlyphBrush),
257	                _T("브러시"), _T("브러시 (아래쪽: 브러시 종류)"));
258	            group(_T("브러시"), left, x + Px(56));
259	        }
260	        // [도형] 모음 + 윤곽선/채우기
261	        {
262	            const int left = x;
263	            const int cw = Px(24), ch = Px(20);
264	            for (int i = 0; i < kGalleryCols * kGalleryRows && i < kShapeKindCount; ++i)
265	            {
266	                const int cx = x + (i % kGalleryCols) * cw;
267	                const int cy = top + (i / kGalleryCols) * ch;
268	                add(Kind::ShapeCell, CRect(cx, cy, cx + cw, cy + ch), ID_SHAPE_FIRST + i, Popup::None, Icon(), _T(""),
269	                    ShapeName(static_cast<ShapeKind>(i)), i);
270	            }
271	            const int moreX = x + kGalleryCols * cw;
272	            add(Kind::ShapeMore, CRect(moreX, top, moreX + Px(16), top + ch * kGalleryRows), 0, Popup::Shapes, Icon(), _T(""), _T("도형 전체 보기"));
273	            const int ox = moreX + Px(22);
274	            const int ow = Px(92);
275	            add(Kind::Labeled, CRect(ox, row1, ox + ow, row1 + bh), 0, Popup::Outline, Icon(), _T("윤곽선"), _T("도형 윤곽선"));
276	            add(Kind::Labeled, CRect(ox, row2, ox + ow, row2 + bh), 0, Popup::Fill, Icon(), _T("채우기"), _T("도형 채우기"));
277	            group(_T("도형"), left, ox + ow);
278	        }
279	        // [굵기]
280	        {
281	            const int left = x;
282	            add(Kind::Large, CRect(x, top, x + Px(52), bottom), 0, Popup::Size, drawnIcon(theme::DrawnIcon::LineWidths),
283	                _T("굵기"), _T("굵기 (Ctrl+Plus / Ctrl+Minus)"));
284	            group(_T("굵기"), left, x + Px(52));
285	        }
286	    }
