    CString error;
    int bad = 0;
    if (!ReadInputs(f, o, error, bad))
    {
        MessageBox(error, _T("함수 그래프"), MB_OK | MB_ICONWARNING);
        GotoDlgCtrl(GetDlgItem(bad));
        return;
