"""MyPaintDlg.cpp / TopBar.cpp / Theme.* 에 함수 그래프 연결 (줄 끝·BOM 유지)"""
import sys, os

d = sys.argv[1]

def edit(name, pairs):
    p = os.path.join(d, name)
    raw = open(p, 'rb').read()
    bom = raw[:3] == b'\xef\xbb\xbf'
    s = raw.decode('utf-8-sig')
    eol = '\r\n' if '\r\n' in s else '\n'
    for a, b in pairs:
        a = a.replace('\n', eol)
        b = b.replace('\n', eol)
        assert s.count(a) == 1, (name, a[:80], s.count(a))
        s = s.replace(a, b)
    open(p, 'wb').write((b'\xef\xbb\xbf' if bom else b'') + s.encode('utf-8'))
    print('edited', name)

