Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Text;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public static class G {
  public delegate bool EnumProc(IntPtr h, IntPtr l);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc f, IntPtr l);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] public static extern IntPtr GetDlgItem(IntPtr h, int id);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern IntPtr SendMessageW(IntPtr h, uint m, IntPtr w, string l);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern IntPtr SendMessageW(IntPtr h, uint m, IntPtr w, StringBuilder l);
  [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr h, uint m, IntPtr w, IntPtr l);
  [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h, uint m, IntPtr w, IntPtr l);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern IntPtr FindWindowEx(IntPtr p, IntPtr a, string cls, string title);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern bool IsWindowEnabled(IntPtr h);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h, IntPtr hdc, uint flags);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern IntPtr GetProp(IntPtr h, string name);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int L, T, R, B; }
  public static List<IntPtr> Windows(uint pid) {
    var list = new List<IntPtr>();
    EnumWindows((h, l) => { uint p; GetWindowThreadProcessId(h, out p); if (p == pid && IsWindowVisible(h)) list.Add(h); return true; }, IntPtr.Zero);
    return list;
  }
}
"@
$WM_COMMAND = 0x111; $WM_SETTEXT = 0xC; $WM_GETTEXT = 0xD; $BM_CLICK = 0xF5
function Text($hwnd) { $sb = New-Object System.Text.StringBuilder 2048; [G]::SendMessageW($hwnd, $WM_GETTEXT, [IntPtr]2048, $sb) | Out-Null; $sb.ToString() }
function Title($hwnd) { $sb = New-Object System.Text.StringBuilder 256; [G]::GetWindowText($hwnd, $sb, 256) | Out-Null; $sb.ToString() }
function Shot($hwnd, $file) {
  Start-Sleep -Milliseconds 900
  $r = New-Object G+RECT; [G]::GetWindowRect($hwnd, [ref]$r) | Out-Null
  $bmp = New-Object System.Drawing.Bitmap ($r.R - $r.L), ($r.B - $r.T)
  $g = [System.Drawing.Graphics]::FromImage($bmp); $hdc = $g.GetHdc(); [G]::PrintWindow($hwnd, $hdc, 2) | Out-Null; $g.ReleaseHdc($hdc); $g.Dispose()
  $bmp.Save((Join-Path $Dir $file)); $bmp.Dispose()
}
$pass = 0; $fail = 0
function Check([string]$name, [bool]$ok, [string]$detail) {
  if ($ok) { $script:pass++; "PASS  $name" } else { $script:fail++; "FAIL  $name :: $detail" }
}

$p = Start-Process -FilePath $Exe -PassThru
Start-Sleep -Milliseconds 1800; $p.Refresh()
$h = $p.MainWindowHandle

# 대화 상자 열기
$before = [G]::Windows([uint32]$p.Id)
[G]::PostMessage($h, $WM_COMMAND, [IntPtr]32967, [IntPtr]0) | Out-Null
Start-Sleep -Milliseconds 1200
$dlg = [G]::Windows([uint32]$p.Id) | Where-Object { $before -notcontains $_ -and (Title $_) -eq '함수 그래프 넣기' } | Select-Object -First 1
Check 'dialog opens' ($dlg -ne $null) 'not found'
if (-not $dlg) { $p | Stop-Process -Force; return }

$combo = [G]::GetDlgItem($dlg, 1140)
$edit = [G]::FindWindowEx($combo, [IntPtr]::Zero, 'Edit', $null)
$info = [G]::GetDlgItem($dlg, 1141)
$details = [G]::GetDlgItem($dlg, 1158)

function SetExpr([string]$e) {
  [G]::SendMessageW($edit, $WM_SETTEXT, [IntPtr]0, $e) | Out-Null
  # CBN_EDITCHANGE (5)
  [G]::SendMessage($dlg, $WM_COMMAND, [IntPtr]((5 -shl 16) -bor 1140), $combo) | Out-Null
  Start-Sleep -Milliseconds 450
}

"initial info: " + (Text $info)
Shot $dlg 'fg_initial.png'

